window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["档案局"] = {"xiangzhendangangongzuobanfa":[{"i":1,"n":"第一条","txt":"为加强乡镇档案工作，推进乡镇档案工作法治化、规范化、科学化，根据《中华人民共和国档案法》及有关法律法规，结合乡镇工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"乡镇档案是指乡镇党委、政府、人大、群团组织（以下简称乡镇机关）及企业事业单位在各项活动中直接形成的具有保存价值的各种文字、图表、声像等不同形式的历史记录。"},{"i":3,"n":"第三条","txt":"乡镇档案工作是乡镇工作的重要组成部分，是一项基础性、支撑性工作，在推进乡镇治理体系和治理能力现代化建设中具有重要作用。"},{"i":4,"n":"第四条","txt":"乡镇应当把档案工作纳入乡镇发展规划、工作计划和考核体系，纳入领导目标管理责任制，纳入乡镇各部门和履行公共服务职能等机构职责范围，切实解决设施设备、人员和经费等实际问题。"},{"i":5,"n":"第五条","txt":"乡镇档案工作在上级档案主管部门监督、指导下，实行统一领导、科学管理的原则，维护档案的完整与安全，便于利用。"},{"i":6,"n":"第六条","txt":"乡镇档案工作所需经费列入乡镇财政预算。"},{"i":7,"n":"第七条","txt":"县级以上地方档案主管部门根据本地区实际，协调有关部门对乡镇档案工作给予政策、资金、项目等方面的支持。"},{"i":8,"n":"第八条","txt":"乡镇应当明确分管档案工作领导，建立档案工作协调机制，处理乡镇档案工作重要事项。"},{"i":9,"n":"第九条","txt":"乡镇应当确定档案机构或岗位（以下简称乡镇档案部门），主管本乡镇档案工作，其职责包括： （一）贯彻执行档案工作的法律法规和方针政策； （二）建立健全档案工作规章制度； （三）对乡镇机关文件材料的收集、整理、归档等工作进行指导和监督； （四）集中管理本乡镇机关的档案； （五）开发档案资源并提供利用； （六）加强档案信息化建设； （七）按照规定向县级综合档案馆移交档案； （八）开展档案宣传、培训，做好档案统计等工作； （九）对乡镇企业事业单位及村级组织的档案工作进行监督、指导； （十）掌握本行政区域档案工作情况，维护档案安全。"},{"i":10,"n":"第十条","txt":"乡镇档案人员应当政治可靠、忠于职守，具备做好档案工作所需要的知识与技能，并保持相对稳定。 档案人员调离岗位或退休的，应当在离岗前办好交接手续。"},{"i":11,"n":"第十一条","txt":"乡镇企业事业单位应当指定人员负责档案工作，确保档案完整、安全，便于利用。"},{"i":12,"n":"第十二条","txt":"乡镇应当加强档案室建设，有条件的可设立乡镇档案馆。"},{"i":13,"n":"第十三条","txt":"乡镇应当设置适宜档案安全保护和利用的档案库房、业务和技术用房、办公用房。 档案库房应当根据档案载体类型分别或分区设置，库房面积应当满足档案法定存放年限需要。"},{"i":14,"n":"第十四条","txt":"档案库房应当远离自然灾害易发地段和易燃易爆等场所，不得毗邻可能危及档案安全的用房，不宜设置在地下。"},{"i":15,"n":"第十五条","txt":"档案库房应当按照防火、防盗、防水（潮）、防光、防尘、防磁、防高温、防有害生物等要求，配备保障档案安全所需的设施设备。"},{"i":16,"n":"第十六条","txt":"档案柜架、档案盒等装具应当符合国家规定。使用密集架的库房楼面均布活荷载标准值应当符合相关要求。"},{"i":17,"n":"第十七条","txt":"乡镇档案部门应当加强档案库房管理，定期检查档案设施设备运行状况，发现问题及时采取措施。"},{"i":18,"n":"第十八条","txt":"乡镇机关及企业事业单位形成的文件材料应当采用耐久、可靠、满足长期保存要求的记录载体和记录方式。 乡镇机关形成的文件材料由各部门整理完毕后向乡镇档案部门归档，乡镇企业事业单位形成的文件材料由各单位整理归档。"},{"i":19,"n":"第十九条","txt":"乡镇应当根据本办法编制本乡镇文件材料归档范围和档案保管期限表，报县级档案主管部门审核同意后执行。机构或职能发生重大变化时应当及时修订并重新报审。"},{"i":20,"n":"第二十条","txt":"归档的文件材料按照有关规章、标准区分类型，分别整理： （一）文书类按照《归档文件整理规则》（DA/T 22）、《文书档案案卷格式》（GB/T 9705）进行整理； （二）科技类按照《科学技术档案案卷构成的一般要求》（GB/T 11822）、《建设项目档案管理规范》（DA/T 28）进行整理； （三）会计类按照《会计档案管理办法》（财政部 国家档案局令第79号）、《会计档案案卷格式》（DA/T 39）进行整理； （四）声像类按照《照片档案管理规范》（GB/T 11821）、《数码照片归档与管理规范》（DA/T 50）、《录音录像档案管理规范》（DA/T 78）进行整理； （五）实物类按照实物类别或保管期限，以件为单位进行整理。 乡镇在专项工作中形成的文件材料，按照相关规定要求进行整理。 电子文件按照《党政机关电子公文归档规范》（GB/T 39362）、《政务服务事项电子文件归档规范》（D"},{"i":21,"n":"第二十一条","txt":"文件材料应当及时归档。文书类文件材料于次年6月底前归档；科技类文件材料在科技活动结束后及时归档；会计类文件材料可由会计部门在会计年度终了后保管1年，于次年3月底前归档；照片、录音录像等声像类材料在活动结束或办理完毕后随时归档；采用办公自动化或其他业务系统的，应当随办随归。 归档时间有特殊规定的，从其规定。"},{"i":22,"n":"第二十二条","txt":"归档的文件材料应当为原件，且真实、准确、齐全、完整。文件材料归档时，交接双方应当根据归档目录清点核对，并履行交接手续。 应当归档的文件材料，任何部门和个人不得拒绝归档或据为己有。"},{"i":23,"n":"第二十三条","txt":"乡镇机关档案由乡镇档案部门集中统一管理。 乡镇企业事业单位的档案原则上自行保管；不具备安全保管条件的，可由乡镇档案部门代管。 涉密档案的管理应当符合保密管理规定。"},{"i":24,"n":"第二十四条","txt":"乡镇应当对已达到保管期限的档案进行鉴定，经鉴定确无保存价值的档案应当按照规定予以销毁，鉴定报告与销毁清册永久保存。 鉴定工作由分管档案工作负责人、档案人员和相关部门人员组成鉴定小组进行。"},{"i":25,"n":"第二十五条","txt":"乡镇档案部门应当编制多种形式的检索工具，开展档案资源开发利用工作，规范利用程序，做好利用效果登记。"},{"i":26,"n":"第二十六条","txt":"乡镇档案部门应当定期对档案保管、档案利用、设施设备和人员等情况进行统计。"},{"i":27,"n":"第二十七条","txt":"乡镇档案部门应当按照规定向县级综合档案馆移交乡镇机关档案，并同时移交检索工具、编研成果。电子档案移交按照国家有关规定执行。"},{"i":28,"n":"第二十八条","txt":"乡镇应当建立健全档案安全工作机制，明确档案安全责任，开展经常性档案安全风险隐患排查整治，制定档案管理应急预案并定期组织演练，确保档案安全。"},{"i":29,"n":"第二十九条","txt":"乡镇应当加强档案信息化工作，推动档案信息化与各项信息化工作协调发展，将档案查阅服务纳入乡镇公共服务事项。 乡镇政务信息系统开发与实施应当考虑档案管理需求。"},{"i":30,"n":"第三十条","txt":"乡镇档案部门和企业事业单位应当配置必要的档案信息化设施设备，使用电子档案管理信息系统，有序开展传统载体档案数字化、电子文件归档与电子档案管理工作，推进乡镇数字档案室、数字档案馆建设。"},{"i":31,"n":"第三十一条","txt":"乡镇应当加强电子档案和档案数字化成果管理，委托其他机构进行档案数字化、信息化服务的，应当对受托方进行监督。"},{"i":32,"n":"第三十二条","txt":"县级档案主管部门应当根据本地区信息化发展水平统筹规划乡镇档案信息化工作，协调相关部门为乡镇搭建网络利用平台、加强档案数字资源建设、实现跨区域跨部门利用等提供条件保障。 鼓励有条件的地区统一部署区域性的电子档案管理信息系统。"},{"i":33,"n":"第三十三条","txt":"县级综合档案馆应当为乡镇档案信息化提供支持，为乡镇档案数字资源备份提供便利，保障档案信息安全。"},{"i":34,"n":"第三十四条","txt":"本办法由国家档案局负责解释。"},{"i":35,"n":"第三十五条","txt":"各省、自治区、直辖市档案主管部门，可结合本地区实际制定实施细则。街道档案工作可参照执行。"},{"i":36,"n":"第三十六条","txt":"本办法自2022年1月1日起施行。国家档案局1998年印发的《乡镇档案工作试行办法》（档发字〔1998〕1号）同时废止。 附件：乡镇文件材料归档范围和档案保管期限表 乡镇文件材料归档范围和档案保管期限表"}],"qiyewenjiancailiaoguidangfanweihedanganbaoguanqixibc8059":[{"i":1,"n":"第一条","txt":"为便于企业正确界定文件材料归档范围，准确划分档案保管期限，促进企业依法经营和规范管理，根据《中华人民共和国档案法》、《中华人民共和国档案法实施办法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所指的企业文件材料是指企业在研发、生产、服务、经营和管理等活动过程中形成的各种门类和载体的记录。"},{"i":3,"n":"第三条","txt":"各级档案行政管理部门依照企业资产关系分别负责对企业文件材料归档范围和档案保管期限表编制工作进行业务指导和监督。"},{"i":4,"n":"第四条","txt":"企业文件材料归档范围是： （一）反映本企业在研发、生产、服务、经营、管理等各项活动和基本历史面貌的，对本企业各项活动、国家建设、社会发展和历史研究具有利用价值的文件材料； （二）本企业在各项活动中形成的对维护国家、企业和职工权益具有凭证价值的文件材料； （三）本企业需要贯彻执行的有关机关和上级单位的文件材料，非隶属关系单位发来的需要执行或查考的文件材料；社会中介机构出具的与本企业有关的文件材料；所属和控股企业报送的重要文件材料； （四）有关法律法规规定应归档保存的文件材料和其他对本企业各项活动具有查考价值的文件材料。"},{"i":5,"n":"第五条","txt":"企业下列文件材料可不归档： （一）有关机关和上级主管单位制发的普发性不需本企业办理的文件材料，任免、奖惩非本企业工作人员的文件材料，供工作参考的抄件等； （二）本企业文件材料中的重份文件，无查考利用价值的事务性、临时性文件，未经会议讨论、未经领导审阅和签发的文件，一般性文件的历次修改稿、各次校对稿，无特殊保存价值的信封，不需办理的一般性来信、来电记录，企业内部互相抄送的文件材料，本企业负责人兼任外单位职务形成的与本企业无关的文件材料，有关工作参考的文件材料； （三）非隶属关系单位发来的不需贯彻执行和无参考价值的文件材料； （四）所属和控股企业报送的供参阅的一般性简报、情况反映，其他社会组织抄送不需本企业办理的文件材料； （五）其他不需归档的文件材料。"},{"i":6,"n":"第六条","txt":"凡属企业归档范围的文件材料，必须按有关规定向本企业档案部门移交，实行集中统一管理，任何个人不得据为己有或拒绝归档。"},{"i":7,"n":"第七条","txt":"企业档案的保管期限定为永久、定期两种，定期一般分为30年、10年。"},{"i":8,"n":"第八条","txt":"永久保管的企业管理类档案主要包括： （一）本企业设立、合并、分立、改制、上市、解散、破产或其他变动过程中形成的文件材料，本企业董事会、监事会、股东会的构成、变更、召开会议、履行职责和维护权益的文件材料； （二）本企业资产和产权登记、评估与证明文件材料，资产和产权转让、买卖、抵押、租赁、许可、变更、保护等凭证性文件材料，对外投资文件材料；本企业资本金核算、确认、划转、变更等文件材料，企业融资文件材料； （三）本企业关于重要问题向有关机关和上级主管单位的请示、报告、报表及其复函、批复，有关机关和上级单位制发的需本企业办理的重要文件材料，行业协会、中介机构等对本企业做出的重要决定、出具的审计、公证、裁定等重要文件材料，本企业与其他组织和个人形成的重要合同、协议及补充协议等文件材料； （四）本企业发展规划、战略决策、重大改革、年度计划和总结文件材料，内部管理制度、规定、办法等文件材料； （五）"},{"i":9,"n":"第九条","txt":"定期保管的企业管理类档案主要包括： （一）本企业资本金管理、资产管理的一般性文件材料，本企业涉及职工权益的一般性文件材料； （二）本企业部门工作或专项工作规划，半年、季度、月份计划与总结等文件材料； （三）本企业召开会议、举办活动的一般性文件材料，发布的一般性公告； （四）本企业经营管理工作的一般性文件材料； （五）本企业生产技术管理工作的一般性文件材料； （六）本企业行政管理工作的一般性文件材料； （七）本企业党群工作的一般性文件材料； （八）本企业关于一般性问题向有关机关和上级主管单位的请示、报告、报表及有关机关和上级主管单位的复函、批复，有关机关和上级主管单位、行业协会制发的需本企业贯彻执行的一般性文件材料和对本企业出具的一般性证明文件，本企业与其他单位和个人形成的一般性合同、协议文件材料； （九）直属单位、所属和控股企业一般性问题的请示、报告、来函与本企业的批复、复函等文件材料"},{"i":10,"n":"第十条","txt":"企业经营管理、生产技术管理、行政管理、党群工作等管理类档案保管期限见附件。"},{"i":11,"n":"第十一条","txt":"本规定的管理类档案保管期限为最低期限，各企业在具体划分时可选择高于本规定的期限。"},{"i":12,"n":"第十二条","txt":"企业产品生产和服务业务、科研开发、基本建设、设备仪器、会计、干部与职工人事等文件材料的归档范围和档案保管期限，按国家有关规定、标准，结合企业实际执行。"},{"i":13,"n":"第十三条","txt":"企业应归档纸质文件材料中，有重要修改意见和批示的修改稿及有发文稿纸或文件处理单的，应与文件正本、定稿一并归档。 企业对于无相应纸质或确实无法输出成纸质的电子文件应纳入归档范围并划分保管期限。 企业对归档的电子文件的元数据要进行相应归档。"},{"i":14,"n":"第十四条","txt":"多个企业联合召开的会议、联合研制的产品、联合建设或研究的项目、联合行文所形成的文件材料，原件由主办企业归档，其他企业将相应的复制件或其他形式的副本归档。"},{"i":15,"n":"第十五条","txt":"企业应依据本规定和国家及专业相关规定，结合本企业生产组织方式、产品和服务特点，编制本企业的各类文件材料归档范围和档案保管期限表。企业应按资产归属关系，指导所属企业根据有关规定规范各类文件材料归档范围和档案保管期限表的编制并审批所属企业的文件材料归档范围和档案保管期限表。"},{"i":16,"n":"第十六条","txt":"中央管理的企业（包括国务院国有资产监督管理委员会监管中央企业、金融企业、中央所属文化企业等）总部的文件材料归档范围和管理类档案保管期限表，报国家档案局同意后执行。 地方国有企业总部编制的文件材料归档范围和管理类档案保管期限表，报同级档案行政管理部门同意后执行。"},{"i":17,"n":"第十七条","txt":"企业资本结构或主营业务发生较大变化时，应及时修订和完善文件材料归档范围和档案保管期限表。"},{"i":18,"n":"第十八条","txt":"企业在编制文件材料归档范围和档案保管期限表时，应全面分析和鉴别本企业形成文件材料的现实作用和历史价值，统筹考虑纸质文件材料与其他载体文件材料的管理要求，准确界定文件材料的归档范围和划分档案保管期限。"},{"i":19,"n":"第十九条","txt":"本规定适用于在中华人民共和国境内注册设立的企业，在境外经营的企业，由企业总部参照本规定提出实施要求；科技事业单位可参照执行。"},{"i":20,"n":"第二十条","txt":"本规定由国家档案局负责解释。"},{"i":21,"n":"第二十一条","txt":"本规定自2013年2月1日起施行。 附件:企业管理类档案保管期限表"}],"qiyedanganguanliguiding":[{"i":1,"n":"第一条","txt":"为加强企业档案工作，推进企业档案科学、规范管理，服务企业各项工作，服务中国特色社会主义事业，根据《中华人民共和国档案法》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称企业档案，是指企业在研发、建设、生产、经营和服务等活动中直接形成的对国家、社会和企业具有保存价值的各种文字、图表、声像等不同形式的历史记录。"},{"i":3,"n":"第三条","txt":"中华人民共和国境内设立的按照规定应当形成档案的企业开展档案收集、整理、保管、利用及监督管理等活动适用本规定。"},{"i":4,"n":"第四条","txt":"企业档案工作是企业履行档案管理职责的行为和活动，是企业不可缺少的基础性、支撑性工作，是国家档案事业的重要组成部分，是维护企业和职工合法权益、服务党和国家工作大局的一项重要工作。"},{"i":5,"n":"第五条","txt":"坚持中国共产党对企业档案工作的领导。企业应当加强对档案工作的组织领导，建立健全档案工作责任制，将档案工作纳入企业整体规划、年度工作计划和考核体系，与业务工作同步部署、同步实施、同步发展。 档案工作经费应当列入企业年度财务预算，为档案工作提供保障。"},{"i":6,"n":"第六条","txt":"企业档案工作实行统一领导、分级管理的原则，维护档案完整与安全，便于开发利用。 国家档案主管部门负责全国企业档案工作的统筹规划和组织协调，建立统一制度，对中央企业（包括国务院国有资产监督管理委员会监管中央企业、中央金融企业、中央所属文化企业等，下同）档案工作实行监督和指导。县级以上地方档案主管部门在职责范围内对本区域企业档案工作实行监督和指导。各级各类开发区管理机构档案部门对本区域企业档案工作实行监督和指导。 中央和地方专业主管部门对所属企业（包括上市公司、境外企业等，下同）档案工作实行监督和指导。企业应当按照资产归属关系对所属单位档案工作实行监督和指导。 国有企业应当按照业务监督和指导关系向档案主管部门或母公司（投资主体）报送企业年度档案工作情况。中央企业总部制定的档案管理制度应当报国家档案主管部门备案。"},{"i":7,"n":"第七条","txt":"企业委托档案服务时，应当按照合法、安全、可控的原则选择依法设立的具备相应资质和服务能力的受托方，签订委托协议，约定服务范围、质量和技术标准等内容，并对受托方进行监督，保证服务质量，确保档案安全。"},{"i":8,"n":"第八条","txt":"企业应当根据规模和管理模式设置档案部门（机构）或者确定负责档案工作的部门（机构），配备与企业规模相适应的专职档案工作人员，满足档案保管利用和业务监督指导的需要。其中档案保管利用人员数量可以根据馆（室）藏档案数量及年度档案增量等确定，档案业务监督指导人员数量可以根据内设部门数量、所属单位数量、项目数量等确定。 中央企业、地方国有大型企业应当在总部设立负责档案工作的职能部门。 企业可以根据需要按照规定设立档案馆。"},{"i":9,"n":"第九条","txt":"企业应当确定分管档案工作负责人、档案部门负责人。企业可以根据需要设置档案专业负责人（档案总监），履行建立档案工作体系、审核专业技术标准、组织实施专项工作、服务主营业务等职责。"},{"i":10,"n":"第十条","txt":"企业档案部门履行下列职责： （一）贯彻执行党和国家有关档案工作法律法规和方针政策，制定档案管理制度和业务标准规范； （二）组织制定并实施本企业档案工作中长期发展规划、年度计划； （三）监督和指导各部门文件材料的形成、积累、鉴定、整理及归档工作； （四）负责档案的收集、整理、保管、保护、鉴定、处置、利用、开发、统计等工作，并按照规定移交档案； （五）组织协调建设项目、科研项目、产品（业务）等档案验收工作； （六）监督和指导所属单位的档案工作； （七）组织实施档案信息化工作； （八）组织开展档案科学研究、技术创新、宣传培训和业务交流等活动。"},{"i":11,"n":"第十一条","txt":"企业各部门（含项目，下同）应当确定档案工作负责人，配备专（兼）职档案工作人员。"},{"i":12,"n":"第十二条","txt":"企业各部门负责本部门文件材料的形成、积累、鉴定、整理、归档，确保其真实、完整、准确。"},{"i":13,"n":"第十三条","txt":"企业应当加强档案工作人才培养和队伍建设，提高档案工作人员业务素质，为其评聘职称创造条件。 档案工作人员应当忠于职守、遵纪守法，具备相应的专业知识与技能。"},{"i":14,"n":"第十四条","txt":"档案工作人员调离岗位或退休的，应当在离岗前办好交接手续。涉密档案工作人员的调离应当按照国家有关保密法律法规执行。"},{"i":15,"n":"第十五条","txt":"企业应当分别设置档案办公用房、阅览用房和档案库房，可以根据需要设置展览（陈列）室、服务器机房、档案接收、整理、修复、消毒、数字化、缩微、安全监控等用房（以下统称业务和技术用房）。 档案库房应当根据载体类型分别设置，不具备条件的应当根据载体类型分区设置。"},{"i":16,"n":"第十六条","txt":"档案办公用房、业务和技术用房等面积应当满足业务开展需要。 阅览用房面积应当满足不同载体类型档案阅览需求，适应涉密与非涉密档案分区阅览的需要。 档案库房面积应当满足企业档案法定存放年限需要，新建档案库房面积应当满足未来至少10年档案存放需要。"},{"i":17,"n":"第十七条","txt":"档案阅览用房、库房、业务和技术用房选址应当利于档案保护，远离易燃、易爆物品和污染源，宜符合《档案馆建筑设计规范》（JGJ 25）规定。 档案库房如无特殊保护，一般不宜设置在地下或顶层，地处湿润地区的还不宜设置在首层。档案库房不得毗邻水房、食堂（厨房）、变配电室、锅炉房、车库等存在安全隐患的场所。"},{"i":18,"n":"第十八条","txt":"档案阅览用房、库房、业务和技术用房建筑设计宜符合《档案馆建筑设计规范》（JGJ 25）规定。 档案库房内不得设置其他用房和明火设施，不应设置除消防以外的给水点，其他给水排水管道不应穿越库房。"},{"i":19,"n":"第十九条","txt":"档案阅览用房、业务和技术用房应当安装视频监控等设施设备。 档案库房应当安装防盗门窗、视频监控、防光窗帘等设施设备，可以选择智能门禁识别、自动报警、出入口控制、电子巡查等安全防范系统。"},{"i":20,"n":"第二十条","txt":"档案办公用房、阅览用房、业务和技术用房均应当配备消防设施并按照规定通过验收。 档案库房应当配备消防系统和火灾自动报警设备。根据档案重要程度和载体类型的不同，选择采用洁净气体、高压细水雾等灭火效率高且对档案无二次损害的灭火设备。"},{"i":21,"n":"第二十一条","txt":"档案库房应当根据需要配备符合国家规定的档案装具，可以参照《档案装具》（DA/T 6）、《直列式档案密集架》（DA/T 7）、《档案密集架智能管理系统技术要求》（DA/T 65）等。 档案库房配备的装具应当与档案库楼面均布活荷载标准值相匹配。档案库楼面均布活荷载标准值不应小于5kN/m2，采用密集架时不应小于12kN/m2。"},{"i":22,"n":"第二十二条","txt":"档案库房应当配备温湿度监测调控系统。档案库房不宜采用水、汽为热媒的采暖系统，确需采用时，应当采取有效措施，严防漏水、漏汽，且采暖系统不应有过热现象。 保存重要档案或具备条件的，可以配置恒温恒湿、通风换气、空气净化等设备。"},{"i":23,"n":"第二十三条","txt":"企业应当按照档案信息化要求，建设、配备能够满足库房现代化管理、档案数字化、电子档案管理需求的设施设备，具体应当符合本规定第七章要求。"},{"i":24,"n":"第二十四条","txt":"形成档案数量较少的企业，应当配备满足安防、消防、温湿度调控和信息化工作基本需求的设施设备。"},{"i":25,"n":"第二十五条","txt":"企业档案部门或者档案工作人员应当参加产品鉴定、科研课题成果审定、项目验收、设备开箱验收等活动，对文件材料的形成、收集、整理与归档进行指导。 企业下达项目计划任务应当同时提出项目文件材料的归档要求；检查项目计划进度应当同时检查项目文件材料积累情况；验收、鉴定项目成果应当同时验收、鉴定项目文件材料归档情况；项目总结应当同时做好项目文件材料归档交接。"},{"i":26,"n":"第二十六条","txt":"企业形成的文件材料应当使用耐久、可靠、满足长期保存要求的记录载体和方式。归档文件材料应当真实、完整、准确，签字及盖章手续完备。 归档的文件材料应当为原件，以复制件归档的应当注明原因及原件存放处。"},{"i":27,"n":"第二十七条","txt":"企业应当按照《中华人民共和国档案法》《企业文件材料归档范围和档案保管期限规定》（国家档案局令第10号）和国家及行业相关规定，确定本企业的文件材料归档范围。"},{"i":28,"n":"第二十八条","txt":"企业应当编制本企业各类文件材料归档范围和档案保管期限表，并按资产归属关系指导所属单位根据有关规定规范各类文件材料归档范围和档案保管期限表的编制并审批所属单位的文件材料归档范围和档案保管期限表。企业档案保管期限分为永久和定期，定期一般分为30年和10年。 中央企业总部的文件材料归档范围和管理类档案保管期限表，报国家档案主管部门同意后执行。 地方国有企业总部编制的文件材料归档范围和管理类档案保管期限表，报同级档案主管部门同意后执行。"},{"i":29,"n":"第二十九条","txt":"企业应当制定统一的档案分类方案。不同门类、形式的档案分类方法应当协调呼应，便于档案的统一管理和利用。分类方案一经确定，应当保持一致，不得随意变动。"},{"i":30,"n":"第三十条","txt":"归档文件材料整理应当遵循文件的形成规律，保持文件之间的有机联系，便于保管和利用。整理方法可以参照《文书档案案卷格式》（GB/T 9705）、《归档文件整理规则》（DA/T 22）、《科学技术档案案卷构成的一般要求》（GB/T 11822）、《照片档案管理规范》（GB/T 11821）、《数码照片归档与管理规范》（DA/T 50）、《录音录像档案管理规范》（DA/T 78）、《会计档案案卷格式》（DA/T 39）等。"},{"i":31,"n":"第三十一条","txt":"企业档案应当逐卷或逐件编制档号。档号应当指代单一，体现档案来源、档案门类、整理分类体系和排列顺序等基本属性。档号编制方法可以参照《档号编制规则》（DA/T 13）、《归档文件整理规则》（DA/T 22）等。"},{"i":32,"n":"第三十二条","txt":"企业撤销部门的未归档文件材料应当明确归档部门和责任人，在部门撤销后1个月内归档，尚未完成的项目（业务）文件材料应当及时移交项目（业务）承接部门按要求归档。 企业人员岗位变动时，应当将待归档文件材料交由接任者按要求归档。"},{"i":33,"n":"第三十三条","txt":"多个企业联合召开的会议、联合研制的产品、联合建设或研究的项目、联合行文所形成的文件材料，原件由主办企业归档，其他企业将相应的复制件或其他形式的副本归档。有其他规定（约定）的从其规定（约定）。"},{"i":34,"n":"第三十四条","txt":"企业文件材料应当经形成部门整理后归档，归档时间可以参照《企业档案工作规范》（DA/T 42）。 企业文件材料归档后，应当按照规定及时向档案部门移交。移交前，形成部门应当编制交接清单，内容包括待移交档案题名、年度、卷（件）号、页数、保管期限、密级等。移交时，交接双方应当按照交接清单所列内容逐项查验，核对无误后交接双方的经办人、负责人在交接清单上签名（盖章）。交接清单一式两份、永久保存。 任何部门或人员不得将应归档文件材料据为己有或者拒绝归档。"},{"i":35,"n":"第三十五条","txt":"需要进行验收（审查或绩效评价）的建设、科研、产品（业务）等项目，还应当按照规定进行档案验收（审查或绩效评价）。"},{"i":36,"n":"第三十六条","txt":"企业可以按照规定通过接受捐献、购买、代存、交换等方式收集档案。"},{"i":37,"n":"第三十七条","txt":"企业应当按全宗管理档案，建立并定期完善全宗卷。全宗卷的编制要求可以参照《全宗卷规范》（DA/T 12）。"},{"i":38,"n":"第三十八条","txt":"企业应当根据档案载体的不同要求对档案进行保管和保护，确保档案实体和信息安全。 企业应当制定档案备份方案，根据档案内容的重要程度分级分类实施异地、异质备份。档案备份应当定期开展，至少每年备份一次。 企业应当制定档案管理应急预案并定期组织演练，做好应急准备，提升应急能力。"},{"i":39,"n":"第三十九条","txt":"企业应当做好档案防火、防盗、防紫外线、防有害生物、防水、防潮、防尘、防高温、防有害气体等工作。 档案库房温湿度要求应当根据档案的重要性和载体等因素确定，宜符合《档案馆建筑设计规范》（JGJ 25）、《电子文件归档与电子档案管理规范》（GB/T 18894）、《磁性载体档案管理与保护规范》（DA/T 15）规定。 档案库房应当保持安全出口、疏散通道畅通，不得存放与档案保管、保护无关的物品。"},{"i":40,"n":"第四十条","txt":"企业档案人员应当监测和记录库房温湿度，根据需要采取调节措施；定期检查维护档案库房设施设备，确保正常运转；定期清扫除尘，保持库房干净整洁；定期检查档案保管情况，发现问题应当及时处理，并建立检查和处理情况台账；记录人员、档案进出库房情况。 档案库房视频监控记录应当至少保存6个月。"},{"i":41,"n":"第四十一条","txt":"企业档案部门应当建立档案台账，定期组织人员对档案数量进行清点，做到账物相符。"},{"i":42,"n":"第四十二条","txt":"档案入库前一般应去污、消毒。 受损、易损的档案应当及时进行修复、复制或做相应技术处理。档案修复应当保持档案内容的完整，维护档案的原貌。档案修复前应当做好登记和检查工作，必要时进行复制备份，并作修复说明。"},{"i":43,"n":"第四十三条","txt":"企业应当定期对已达到保管期限的档案进行鉴定处置。 鉴定工作由企业档案部门牵头、相关部门参加，必要时可邀请相关领域专家参与。鉴定工作结束后，应当形成鉴定意见。鉴定意见应当由企业法定代表人或其授权人（分管档案工作的负责人）、档案部门负责人和相关部门负责人组成的企业档案鉴定委员会（小组）审批。 对仍需继续保存的档案，应当重新划定保管期限并做出标注；对确无保存价值档案，按照规定予以销毁。"},{"i":44,"n":"第四十四条","txt":"销毁档案按照以下程序办理： （一）企业档案部门编制档案销毁清册，列明拟销毁档案的档号、文号、责任者、题名、形成时间、应保管期限、已保管期限和拟销毁时间等内容，报企业档案鉴定委员会（小组）审批； （二）企业档案鉴定委员会（小组）在档案销毁清册上签署意见； （三）企业档案部门组织档案销毁工作，并与相关业务部门共同派员监销。档案销毁前，监销人应当按照档案销毁清册所列内容进行清点核对，确认无误后档案部门做好档案出库记录；档案销毁后，监销人应当在档案销毁清册上签名、盖章。档案销毁清册永久保存。 档案销毁应当在指定场所进行。 电子档案和传统载体档案数字化成果的销毁还应当符合本规定第六十六条要求。 涉密档案的销毁应当符合《国家秘密载体销毁管理规定》。"},{"i":45,"n":"第四十五条","txt":"企业发生资产与产权变动的，应当按照业务监督指导关系及时向相应档案主管部门或母公司（投资主体）报告有关情况。国有企业按照《国有企业资产与产权变动档案处置办法》（国家档案局令第17号）开展档案处置工作。"},{"i":46,"n":"第四十六条","txt":"企业应当积极开展档案利用工作，建立健全档案利用制度，根据档案的密级、内容和利用方式，规定不同的利用权限、范围和审批手续。 企业提供利用档案时，不得损害国家安全和利益，不得侵犯他人的合法权益。"},{"i":47,"n":"第四十七条","txt":"利用企业档案应当严格执行利用制度，履行档案查阅、复制、借出审批和登记手续。通过网络方式提供利用时，应当采取身份认证、权限控制等安全措施。 企业档案一般不得对外借出，确因工作需要且根据国家有关规定必须借出的，应当严格按照规定办理相关手续。利用者应当妥善保管和利用借阅的档案，严禁篡改和损坏，确保档案的安全完整，并在规定时间内归还。 企业人员办理退休或离岗手续时，应当经由档案部门确认已归还借阅的档案。"},{"i":48,"n":"第四十八条","txt":"档案部门应当编制检索工具，满足手工检索和计算机检索需要。 档案工作人员应当进行档案利用效果登记，对利用活动及时跟踪和监督。"},{"i":49,"n":"第四十九条","txt":"企业应当积极推进档案信息开发工作，采取编制专题汇编、大事记、组织沿革、项目（工程）简介、企业史志等，以及举办陈列展览、拍摄专题片、建设档案专题数据库等多种形式，发挥档案价值。 企业应当加强对突发事件应对管理活动相关档案的研究整理和开发利用，为突发事件应对管理提供文献参考和决策支持。 企业宜围绕重大活动、重点工作和重要历史节点开展档案编研。"},{"i":50,"n":"第五十条","txt":"企业应当做好档案统计工作，对所保管档案情况、年度档案及人员出入库情况、档案设施设备情况、档案利用情况、档案交接情况、档案鉴定处置情况、档案信息化建设情况、档案人员情况、档案委托服务情况等定期统计、建立台账，并按照《全国档案事业统计调查制度》填写报送统计报表。"},{"i":51,"n":"第五十一条","txt":"企业应当按照国家有关规定，定期向档案馆移交档案。 企业移交档案后需要利用的，接收档案的档案馆应当提供便利。"},{"i":52,"n":"第五十二条","txt":"企业向档案馆移交档案时，应当按照相关规定标注档案密级变更情况，并附具档案开放审核意见。 对已移交进馆的档案，企业应当按照国家有关规定配合档案馆做好档案降解密和开放审核工作。"},{"i":53,"n":"第五十三条","txt":"企业应当加强档案信息化建设，将档案信息化纳入企业信息化总体规划。具备条件的企业宜建设数字档案馆（室）。"},{"i":54,"n":"第五十四条","txt":"企业应当配置满足档案数字资源管理需要的网络设施、服务器及存储设备、基础软件、安全保障系统、终端及辅助设备等。"},{"i":55,"n":"第五十五条","txt":"企业电子档案管理信息系统应当符合国家安全保密要求，具备收集、整理、保存、利用、鉴定与处置、统计、格式转换、审计、备份、系统管理等基本功能，并与企业其他信息系统相互衔接，规范运行、定期维护。具体可以参照《档案信息系统运行维护规范》（DA/T 56）。"},{"i":56,"n":"第五十六条","txt":"企业应当充分考虑办公自动化系统、产品数据（业务）管理系统、企业资源计划系统、会计核算系统、电子邮件系统、门户网站、社交媒体等信息系统中电子文件的归档需求，选择适宜的电子文件格式，捕获相应的元数据，完备归档接口，按照要求完成（进行）电子文件归档。"},{"i":57,"n":"第五十七条","txt":"企业各信息系统批量和零散形成的、以及外部接收的属于归档范围的电子文件，均应当归档，并采取有效措施确保电子文件真实、完整、可用、安全。电子文件元数据应与电子文件一并归档。"},{"i":58,"n":"第五十八条","txt":"电子文件归档时间应当与其他载体文件归档时间相协调，一般不晚于同批次其他载体文件归档时间。无其他载体的电子文件可以在办理完毕后实时归档。"},{"i":59,"n":"第五十九条","txt":"电子文件的归档格式应当符合格式开放、不绑定软硬件、文件自包含、可转换等长期保存要求。不符合长期保存要求的，应当转换为符合要求的归档格式或将专用软件一并归档。"},{"i":60,"n":"第六十条","txt":"电子文件与传统载体文件并存的，应当在电子档案管理信息系统内将二者建立关联。 电子文件整理应当按照本规定第三十、三十一条执行，具体可以参照《电子文件归档与电子档案管理规范》（GB/T 18894）。"},{"i":61,"n":"第六十一条","txt":"电子档案管理应当实施全方位的安全与保密措施，确保电子档案安全。"},{"i":62,"n":"第六十二条","txt":"企业电子档案应当根据国家有关规定，按照《电子档案移交与接收办法》的信息组织方式实施在线和离线存储，重要档案应当离线存储、一式三套。"},{"i":63,"n":"第六十三条","txt":"企业应当制定电子档案管理信息系统备份策略，实施电子档案管理信息系统备份管理。"},{"i":64,"n":"第六十四条","txt":"企业应当定期对电子档案的真实性、完整性、可用性、安全性进行检测，对存在问题或风险的电子档案及时进行迁移或采用经过评估的其他技术延长其可用时间。 电子档案迁移应当按照确认需求、评估风险、制定实施方案、测试与实施、评估与结果报告的步骤进行，确保过程可控。迁移活动应当在电子档案管理过程元数据中记录。 电子档案迁移后，根据本企业实际，对迁移前的电子档案进行销毁或留存。"},{"i":65,"n":"第六十五条","txt":"企业应当积极开展传统载体档案数字化工作，保证数字化过程规范安全。具体可以参照《纸质档案数字化规范》（DA/T 31）、《录音录像档案数字化规范》（DA/T 62）等。"},{"i":66,"n":"第六十六条","txt":"销毁电子档案和传统载体档案数字化成果，应当确保在线存储设备、容灾备份系统、离线存储介质中均不可识读。"},{"i":67,"n":"第六十七条","txt":"来源可靠、程序规范、要素合规的电子档案与传统载体档案具有同等效力，可仅以电子形式作为凭证使用。"},{"i":68,"n":"第六十八条","txt":"企业应当接受并配合档案主管部门依法组织开展的档案检查，检查内容包括：档案工作责任制和管理制度落实情况；档案库房、设施、设备配置使用情况；档案工作人员管理情况；档案收集、整理、保管、提供利用等情况；档案信息化建设和信息安全保障情况；对所属单位等的档案工作监督和指导情况。"},{"i":69,"n":"第六十九条","txt":"企业发现存在档案安全隐患的，应当及时采取措施，消除档案安全隐患。发生档案损毁、信息泄露等情形的，应当及时向档案主管部门报告。 有下列情形之一的，应当视为存在档案安全隐患： （一）档案库房选址、设计、建设不规范，库房面积严重不足的； （二）缺乏必要的设施、设备，或者设施、设备老化，性能不符合要求，存在档案保管安全隐患的； （三）档案资源未集中统一管理，面临散失、损毁危险的； （四）电子档案管理信息系统或者功能模块不符合安全保护要求，关键功能缺失，无法确保电子档案来源可靠、程序规范、要素合规的； （五）对电子档案的接收、存储、备份不规范，无法确保电子档案长期有效的； （六）档案开放审核、利用程序不规范，致使开放、利用的档案内容存在安全风险的； （七）委托档案服务不符合规定的； （八）存在其他严重危及档案实体和信息安全的。"},{"i":70,"n":"第七十条","txt":"档案主管部门发现企业存在档案安全隐患的，应当责令限期整改，消除档案安全隐患。"},{"i":71,"n":"第七十一条","txt":"国有企业应当按照资产归属关系定期对所属单位的档案工作开展检查考核。检查考核时应当制定计划、明确标准、完善过程记录、反馈结果、督促问题归零，确保检查考核工作形成闭环。"},{"i":72,"n":"第七十二条","txt":"企业任何单位和个人有权向档案主管部门和有关机关举报企业档案违法行为。 接到举报的档案主管部门或者有关机关应当及时依法处理。"},{"i":73,"n":"第七十三条","txt":"有下列情形之一的，档案主管部门和企业应当根据实际情况进行表彰奖励： （一）档案收集、整理、移交成绩显著的； （二）档案保管、保护和现代化管理成绩显著的； （三）档案开发利用、宣传、教育取得突出效果的； （四）在档案学理论研究、档案科研方面做出重要贡献的； （五）在重大活动、突发事件应对管理档案工作和档案应急处置中表现突出的； （六）同违反档案法律、法规的行为作斗争，表现突出的。"},{"i":74,"n":"第七十四条","txt":"对违反本规定的企业或个人，根据《中华人民共和国档案法》等法律法规予以处理。"},{"i":75,"n":"第七十五条","txt":"各省、自治区、直辖市档案主管部门可以根据本规定制定实施细则。"},{"i":76,"n":"第七十六条","txt":"科技事业单位可以参照本规定执行。"},{"i":77,"n":"第七十七条","txt":"本规定由国家档案局负责解释，自2023年10月1日起施行。国家档案局2002年7月22日发布的《企业档案管理规定》同时废止。"}],"gejigeleidanganguanshoujidanganfanweideguiding":[{"i":1,"n":"第一条","txt":"各级各类档案馆要贯彻科学发展、以人为本的理念，在档案行政管理部门的监督指导下，按照统一规划、分级管理的原则，依法开展档案收集工作，将属于本馆收集范围的具有长久保存价值的档案收集进馆。"},{"i":2,"n":"第二条","txt":"各级综合档案馆依法接收本级下列组织机构的档案： 1.中国共产党委员会及所属各部门； 2.人民代表大会及其常设机构； 3.人民政府及其所属各部门和单位； 4.人民政协及其常设机构； 5.人民法院、人民检察院； 6.各民主党派机关； 7.工会、共青团、妇联等人民团体； 8.国有企业、事业单位。 各级综合档案馆可全部或部分接收以上机构的下属单位和临时机构的档案。 乡镇机构形成的档案列入县级综合档案馆接收范围。"},{"i":3,"n":"第三条","txt":"新中国成立前本行政区内各个历史时期政权机构、社会组织、著名人物的档案列入综合档案馆收集范围。 本行政区内重大活动、重要事件形成的档案、涉及民生的专业档案列入综合档案馆收集范围。 经协商同意，综合档案馆可以收集或代存本行政区内社会组织、集体和民营企事业单位、基层群众自治组织、家庭和个人形成的对国家和社会有利用价值的档案，也可以通过接受捐赠、购买等形式获取。"},{"i":4,"n":"第四条","txt":"各级部门档案馆，收集本部门及其直属单位形成的档案，但其中履行行政管理职能的档案，要按有关规定定期向综合档案馆移交。"},{"i":5,"n":"第五条","txt":"各级专门档案馆，收集本行政区内某一专门领域或特定载体形态的专门档案或档案副本。"},{"i":6,"n":"第六条","txt":"国有企业、事业单位设立的档案馆，收集本单位及其所属机构形成的档案。国有企业发生破产转制，事业单位发生撤销等情况，其档案可按照有关规定由本级综合档案馆接收。"},{"i":7,"n":"第七条","txt":"省级以上（含省级）档案馆接收保管期限为永久的档案，省级以下（不含省级）档案馆接收保管期限为永久和30年以上（含30年）的档案。"},{"i":8,"n":"第八条","txt":"档案馆要适应信息化建设的需要，收集电子档案和纸质档案的数字化副本。有条件的档案馆应根据国家灾害备份的要求，建立电子文件备份中心，开展电子文件备份工作。"},{"i":9,"n":"第九条","txt":"档案馆在收集档案时，应同时收集有助于了解档案内容、立档单位历史的资料，收集有助于管理和利用档案所必需的专用设备。"},{"i":10,"n":"第十条","txt":"各级各类档案馆要根据本规定制定本馆的收集档案范围细则和工作方案，经上级档案行政管理部门同意后施行。"},{"i":11,"n":"第十一条","txt":"本规定由国家档案局负责解释。"},{"i":12,"n":"第十二条","txt":"本规定自发布之日起实施。《各级国家档案馆收集档案范围的规定》（1986年2月7日国家档案局发布）同时废止。"}],"gejiguojiadanganguanguancangdanganjiemihehuafenkonf04836":[{"i":1,"n":"第一条","txt":"为正确处理保守国家秘密与开放档案的关系，根据《中华人民共和国档案法》和《中华人民共和国保守国家秘密法》，制定本规定。"},{"i":2,"n":"第二条","txt":"各级国家档案馆保存的1991年1月1日前形成的标有“绝密”、“机密”、“秘密”字样的档案（以下简称涉密档案），其解密工作，由各级国家档案馆负责进行。 对形成将满30年的涉密档案，原档案形成的机关、单位，认为仍属国家秘密的，应当自该档案形成届满30年之日前的6个月，通知（以文书形式，以下皆同）同级档案行政管理机关和国家档案馆，逾期未通知延长保密期限的，由各级国家档案馆按照本规定第七条办理。"},{"i":3,"n":"第三条","txt":"1991年1月1日前形成的未进馆的涉密档案，其解密工作由各档案形成机关、单位负责进行，在向各级国家档案馆移交前，要完成清理工作，否则不予受理。"},{"i":4,"n":"第四条","txt":"各级国家档案馆保存的1991年1月1日后形成的涉密档案，未接到保密期限变更通知的，自保密期限届满之日起，即自行解密。"},{"i":5,"n":"第五条","txt":"各级国家档案馆保存的经济、科学、技术、文化类涉密档案，根据需要认为有必要提前开放的，应当向原档案形成机关、单位发出要求提前解密的通知，有关机关、单位应当在接到通知的6个月内作出答复，未予答复的，档案馆可根据有关规定办理。"},{"i":6,"n":"第六条","txt":"原档案形成的机关、单位被撤销或者合并，对其所形成的涉密档案的密级和保密期限作出处理决定的工作，由承担其原职能的单位负责；无相应的承担机关、单位的，由有关档案馆负责。"},{"i":7,"n":"第七条","txt":"各级国家档案馆保存的中华人民共和国成立前形成的历史档案，中华人民共和国成立后形成满30年的已解密的档案和未定密级的其他档案，凡涉及下列内容的应当控制使用： （一）涉及我党和国家重大问题、重大政治事件尚未作出结论的、不宜公开的，对社会开放会影响党内团结、党和国家机关工作正常开展的档案； （二）涉及各级党和政府领导人及社会各界著名爱国进步人士的政治历史评价及工作与生活中不宜公开的，对社会开放有损个人形象、人格尊严和声誉的档案； （三）涉及我党和国家秘密工作的组织关系、工作方法、策略手段、情报来源的，对社会开放会使保护党和国家安全与利益的措施、手段的可靠性降低或者失效的档案； （四）涉及我党和国家及其领导人与外国政党组织及其领导人之间秘密关系的，对社会开放会影响两党、两国正常关系以及其他对外关系的档案； （五）涉及民国时期敌特机关破坏我党地下组织的，为进行策反纯属捏造的，对社会开放会损害我党"},{"i":8,"n":"第八条","txt":"各级国家档案馆馆藏档案的划控工作，由档案馆负责组织力量，根据本规定的有关条款确定的标准负责进行，必要时聘请同级档案行政管理部门、保密工作部门和文件制发单位组成专门小组共同进行。 被聘请的有关部门应当积极配合。"},{"i":9,"n":"第九条","txt":"各级国家档案馆对所保存的国家秘密档案和划入控制使用范围的档案，应当依照国家有关法规并根据实际工作需要，制定审批手续并严格执行，不得擅自开放或者扩大利用、接触范围。 各级国家档案馆应当对其工作人员进行保密教育，监督其履行保密义务。"},{"i":10,"n":"第十条","txt":"对违反本规定泄露国家秘密或者造成其他严重后果的行为人，应当根据有关法律规定酌情给予行政处分或者追究民事法律责任；情节严重的，依法追究刑事法律责任。"},{"i":11,"n":"第十一条","txt":"各级国家档案馆应根据本规定制定具体的工作细则。"},{"i":12,"n":"第十二条","txt":"本规定由国家档案局负责解释。各级档案行政管理部门、保密工作部门对本规定的实施负有指导和监督的职权。"},{"i":13,"n":"第十三条","txt":"本规定自发布之日起施行，过去制发的有关规定凡与本规定相抵触的，以本规定为准。"}],"guojiadanganguandangankaifangbanfa":[{"i":1,"n":"第一条","txt":"为了推进和规范各级国家档案馆档案开放工作，进一步加强档案管理、促进档案利用，充分发挥档案在党和国家各项事业发展中的作用，根据《中华人民共和国档案法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称档案开放，是指国家档案馆按照法定权限将形成时间达到一定年限、无需限制利用的馆藏档案经过法定程序向社会提供利用的活动。"},{"i":3,"n":"第三条","txt":"档案开放应当遵循合法、及时、平等和便于利用的原则，实现档案有序开放、有效利用与档案实体和信息安全相统一。"},{"i":4,"n":"第四条","txt":"国家档案馆应当建立健全档案开放工作制度，积极稳妥地推进档案开放，加强档案利用服务能力建设，保障单位和个人依法利用档案的权利。"},{"i":5,"n":"第五条","txt":"国家档案主管部门负责统筹协调、监督指导全国档案开放工作，研究制定档案开放有关政策和工作规范。 县级以上地方档案主管部门负责统筹协调本行政区域的档案开放工作，对本行政区域内地方各级国家档案馆的档案开放工作实行监督指导。"},{"i":6,"n":"第六条","txt":"国家档案馆负责各自分管范围内馆藏档案的开放。国家对档案开放的权限另有规定的，从其规定。"},{"i":7,"n":"第七条","txt":"自形成之日起满二十五年的国家档案馆的档案，经开放审核后无需限制利用的应当及时向社会开放。经济、教育、科技、文化等类档案，经开放审核后可以提前向社会开放。"},{"i":8,"n":"第八条","txt":"自形成之日起已满二十五年，但具有下列情形之一的国家档案馆的档案，可以延期向社会开放： （一）涉及国家秘密且保密期限尚未届满、解密时间尚未到达或者解密条件尚未达成的； （二）涉及国家和社会重大利益，开放后可能危及国家安全和社会稳定的； （三）涉及知识产权、个人信息，开放后会对第三方合法权益造成损害的； （四）其他按照有关法律、行政法规和国家有关规定应当限制利用的。"},{"i":9,"n":"第九条","txt":"国家档案馆应当根据本办法第八条的规定，结合职责权限和馆藏档案实际，会同档案形成单位或者移交单位依法依规确定延期向社会开放档案的具体标准和范围。"},{"i":10,"n":"第十条","txt":"国家档案馆不得擅自开放归属和管理权限不属于本馆的历史档案。如需开放，应当按照有关规定征得对该档案有归属和管理权限的档案馆的同意。"},{"i":11,"n":"第十一条","txt":"国家档案馆以接受捐献、寄存方式收集的档案，是否开放应当按照与捐献、寄存档案的单位和个人的约定办理。未作约定的，国家档案馆应当征求捐献、寄存档案的单位和个人意见。无法取得意见的，由国家档案馆按照本办法有关规定办理。"},{"i":12,"n":"第十二条","txt":"国家档案馆的档案应当依照有关法律、行政法规以及本办法的规定，进行开放审核，分期分批向社会开放。"},{"i":13,"n":"第十三条","txt":"国家档案馆向社会开放档案应当按照以下程序进行： （一）计划。研究提出工作方案，明确档案开放工作目标、任务和要求，并报同级档案主管部门批准。 （二）组织。按照同级档案主管部门批准的工作方案牵头组织实施档案开放工作。 （三）审核。会同档案形成单位或者移交单位共同对馆藏档案进行开放审核。 （四）确认。按照本办法第十五条的规定确认档案开放审核结果。 （五）公布。以适当方式向社会公布开放档案的目录。"},{"i":14,"n":"第十四条","txt":"县级以上地方档案主管部门应当协调建立本地区馆藏档案开放审核协同机制，明确国家档案馆牵头，档案形成单位或者移交单位参与，双方共同负责馆藏档案开放审核。 馆藏档案开放审核的具体规定由国家档案主管部门另行制定。"},{"i":15,"n":"第十五条","txt":"馆藏档案开放审核结果应当由国家档案馆和档案形成单位或者移交单位协商一致确定。其中，延期向社会开放的档案，应当由国家档案馆将档案目录报同级档案主管部门审核。"},{"i":16,"n":"第十六条","txt":"国家档案馆应当将有关档案开放的信息通过互联网政务媒体、新闻发布会以及报刊、广播、电视等便于公众知晓的方式及时予以公布，并通过网站或者其他方式定期公布开放档案的目录。"},{"i":17,"n":"第十七条","txt":"国家档案馆应当对延期开放的馆藏档案定期评估，因情势变化不再具有法律、行政法规以及本办法规定的延期向社会开放情形的，在履行相关程序后向社会开放。"},{"i":18,"n":"第十八条","txt":"单位和个人持有合法证明可以利用国家档案馆已经开放的档案。机关、团体、企业事业单位和其他组织以及公民利用未开放档案应当向国家档案馆提出申请，按照规定办理有关手续。 国家档案馆应当依照有关法律、行政法规以及本办法的规定，制定档案利用的具体办法，明确档案利用的条件、方式、范围、程序等，并向社会公布。"},{"i":19,"n":"第十九条","txt":"国家档案馆应当设置专门的档案利用场所并配备相应的设施、设备，通过信函、电话、网站、电子邮件和互联网政务媒体等多种方式，建立完善档案利用渠道，简化手续，积极为档案利用创造条件、提供便利。"},{"i":20,"n":"第二十条","txt":"国家档案主管部门统筹建设开放档案查询利用平台，推动开放档案跨区域共享利用。"},{"i":21,"n":"第二十一条","txt":"单位和个人到国家档案馆利用档案，应当遵守档案利用的相关规定，并对所利用的档案负有保护的义务。"},{"i":22,"n":"第二十二条","txt":"存在破损或者字迹褪变、扩散等情形且尚未完成修复的档案，如提供利用可能造成档案进一步受损的，国家档案馆可以暂缓提供利用。"},{"i":23,"n":"第二十三条","txt":"已经印刷、复印、缩微、翻拍及数字化等复制处理的档案，国家档案馆应当使用复制件代替原件提供利用。古老、珍贵和重要档案，原则上不提供原件利用。"},{"i":24,"n":"第二十四条","txt":"单位和个人在国家档案馆利用档案需要复制的，可以由国家档案馆代为办理，复制档案的数量由国家档案馆根据具体情况酌情决定。因档案保存状况和档案载体特点等原因不适宜复制的，国家档案馆可以不予复制。"},{"i":25,"n":"第二十五条","txt":"单位和个人使用从国家档案馆摘录、复制的档案，应当遵守有关法律、行政法规和国家有关规定，不得损害国家利益、社会公共利益和第三方合法权益。在公开发表、出版的作品中使用国家档案馆尚未公布的档案，还应当遵守保管该档案的国家档案馆的有关规定。"},{"i":26,"n":"第二十六条","txt":"举办展览、展示等活动需要使用国家档案馆档案的，一般应当使用复制件代替原件，档案原件原则上不外借。"},{"i":27,"n":"第二十七条","txt":"档案主管部门应当协调有关部门，为国家档案馆开展档案开放工作创造条件、提供保障。"},{"i":28,"n":"第二十八条","txt":"档案形成单位或者移交单位应当为国家档案馆开展档案开放工作提供便利，对应当共同负责的档案开放审核工作，不得拒绝、推诿、敷衍、拖延。无正当理由拒不履行档案开放审核职责的，由档案主管部门责令限期改正。"},{"i":29,"n":"第二十九条","txt":"国家档案馆应当不断提高档案开放工作水平，改善档案利用服务条件，听取社会公众意见，完善反馈机制，接受社会监督。"},{"i":30,"n":"第三十条","txt":"档案主管部门应当会同有关部门加强对国家档案馆档案开放工作的监督检查。对不按照规定向社会开放、提供利用档案的，档案主管部门应当督促整改，依法依规给予相应处理。"},{"i":31,"n":"第三十一条","txt":"国家档案馆应当在每年1月31日前向同级档案主管部门提交上一年度档案开放工作年度报告。 年度报告应当包括档案开放工作计划执行情况、提供档案利用服务情况以及档案利用典型案例等。"},{"i":32,"n":"第三十二条","txt":"外国人、无国籍人、外国组织利用国家档案馆已经开放的档案，适用本办法。国家另有规定的除外。"},{"i":33,"n":"第三十三条","txt":"国家档案馆应当根据本办法，结合工作实际，制定本馆档案开放工作的具体操作规定，报同级档案主管部门备案。"},{"i":34,"n":"第三十四条","txt":"本办法自2022年8月1日起施行。国家档案局1991年12月26日发布的《各级国家档案馆开放档案办法》、《外国组织和个人利用我国档案试行办法》同时废止。之前有关档案开放的规定与本办法不一致的，按照本办法执行。"}],"guojiazhongdianjianshexiangmudanganguanlidengjiban07fe03":[{"i":1,"n":"第一条","txt":"为了做好国家重点建设项目档案工作，确保重点建设项目档案的完整、准确、系统和有效利用，根据《中华人民共和国档案法》及有关法规，特制定本登记办法。"},{"i":2,"n":"第二条","txt":"重点建设项目档案既是重点建设项目的历史记录，也是项目投产后运行、维修、管理、改扩建和技改等工作的重要依据。为了及时掌握国家重点建设项目档案工作情况，加强监督和指导，从１９９７年开始，国家档案局建立国家重点建设项目档案管理的登记制度。"},{"i":3,"n":"第三条","txt":"登记工作的组织： １、国家档案局每年转发国家计委发布的国家重点建设项目名单、并统一部署对国家重点建设项目档案的登记工作；各项目主管部门的档案机构和项目所在地的省级档案行政管理部门应做好对本部门和本地区国家重点建没项目档案管理登记工作的组织、指导和监督工作。 ２、凡新建、在建、收尾和竣工试生产的国家重点建设项目，按隶属关系组织登记。属于国务院行业主管部门的，由项目主管部门的档案机构负责组织填写“国家重点建设档案管理登记表”，同时抄送项目所在地省级档案行政管理部门，便于相互配合，监督指导；属于地方的，由项目所在地省级档案行政管理部门负责组织填写“国家重点建设项目档案管理登记表”。 ３、登记表共分三种，表一、表二、表三分别于项目开工后６个月内、项目档案预验收后１个月内和项目正式竣工验收后１个月内填写，并逐级报至国家档案局经济科技档案业务指导司。 ４、国家档案局于每年１２月底汇总国家重点建设项"},{"i":4,"n":"第四条","txt":"登记工作的要求： １、项目主管部门档案机构应与地方档案行政管理部门互通情况，互相合作，以保证做好国家重点建设项目的档案管理登记工作。 ２、项目主管部门档案机构和省级档案行政管理部门对于新建项目，应按本规定第三条第２款及时组织和监督建设单位（或项目法人）做好档案管理登记，建立档案工作。对于未进行竣工验收的国家重点建设项目，每年填写“表一”报送，以便及时了解项目及项目档案工作的进展和变化情况。 ３、要保证项目档案工作与项目建设同步进行，特别要认真做好项目档案的预验收工作。国务院各行业主管部门档案机构应主动与项目建设部门加强联系，根据项目计划工期和进度，及时对登记的项目提出档案验收要求，并会同或委托项目所在地省级档案行政管理部门组织预验收。隶属于地方的项目，省级档案行政管理部门应根据相应的工作要求，及时对登记的项目组织预验收。预验收结束后，验收组织单位不论本年度是否已报送过“表一”，应按本登"},{"i":5,"n":"第五条","txt":"为确保国家重点建设项目的正常秩序，任何部门和单位不得向国家重点建设项目和省级重点建设项目收取任何名目的工程档案保证金和任何形式的档案管理登记费用。违反上述规定的属乱收费行为，由各级价格检查机构依法查处。"},{"i":6,"n":"第六条","txt":"对于重大技改项目和一般基本建设大中型项目的档案管理登记工作，可参照本办法执行或制定具体的实施办法。"},{"i":7,"n":"第七条","txt":"本办法由国家档案局和国家计委负责解释。"},{"i":8,"n":"第八条","txt":"本办法自发布之日起执行。"}],"guoyouqiyezichanyuchanquanbiandongdanganchuzhibanf1efa04":[{"i":1,"n":"第一条","txt":"为规范国有企业在资产与产权变动中的档案处置工作，确保档案完整安全，防止国有资产流失，维护企业合法权益和职工切身利益，根据《中华人民共和国档案法》等相关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"国有企业合并、分立、终止（包括解散、破产等）、控制权变更、分离办社会职能等资产与产权变动涉及的档案处置工作适用本办法。"},{"i":3,"n":"第三条","txt":"国有企业档案（含照片、胶片、磁带、磁盘、光盘、实物等档案）是国有企业全部活动的真实记录和宝贵财富，是企业资产的依据和凭证，是国家档案资源的重要组成部分，任何单位或个人在资产与产权变动过程中不得擅自处置。"},{"i":4,"n":"第四条","txt":"国有企业资产与产权变动档案处置遵循下列原则： （一）维护国家安全和国家利益，保守国家秘密和企业商业秘密，防止档案散失。 （二）依法依规，区别情况，分类处置。 （三）保障档案的安全，便于档案的利用。 （四）有利于企业保持经营管理的连续性。"},{"i":5,"n":"第五条","txt":"对在档案处置工作中作出突出贡献的单位或个人，按照国家有关规定给予表彰、奖励。对违反本办法的单位或个人，根据《中华人民共和国档案法》《中华人民共和国档案法实施办法》《档案管理违法违纪行为处分规定》等予以处理。"},{"i":6,"n":"第六条","txt":"国有企业资产与产权变动档案处置工作是国有企业资产与产权变动工作的一项重要内容。各有关单位应当将档案处置纳入资产与产权变动工作，同步进行。"},{"i":7,"n":"第七条","txt":"各级档案主管部门应当作为同级政府国有企业资产与产权变动工作机制成员单位。各级档案主管部门会同国有资产监督管理机构或企业主管部门，加强对国有企业资产与产权变动档案处置工作的组织协调、监督和指导。 国有企业或其上级主管部门负责所属企业资产与产权变动档案处置工作的组织协调、监督和指导。"},{"i":8,"n":"第八条","txt":"资产与产权变动国有企业是档案处置工作的责任主体，应当明确分管负责人和相关部门职责，主动及时向相应的档案业务监督指导单位汇报有关情况，确保档案处置工作顺利开展。 国有企业破产的，由破产管理人（清算组）负责档案处置工作。"},{"i":9,"n":"第九条","txt":"资产与产权变动国有企业应当按照本办法及相关各方的约定编制档案处置方案，内容包括企业资产与产权变动的方式、档案处置工作流程、各类档案的数量及归属与流向、档案移交时间、相关经费安排等。"},{"i":10,"n":"第十条","txt":"中央管理企业总部编制的档案处置方案，报国家档案局审核同意后执行。地方国有企业总部编制的档案处置方案，报同级档案主管部门审核同意后执行。国有企业应当按照资产隶属关系指导所属企业编制档案处置方案并进行审核。 负责档案处置方案审核的单位应当对方案实施情况进行跟踪检查，发现问题及时纠正。"},{"i":11,"n":"第十一条","txt":"档案处置工作流程包括： （一）确定待处置档案范围，清点档案数量。 （二）收集、整理尚未归档的文件材料。 （三）按照有关规定做好档案的鉴定工作。鉴定工作由企业分管档案工作的负责人和档案、财务、法务等部门人员共同负责；国有企业破产的，由破产管理人（清算组）负责。 （四）对拟销毁的档案编制清册，按照档案销毁程序予以销毁。销毁清册随国有企业资产与产权变动中形成的其他文件材料一起归档，永久保存。 （五）对拟留存的档案按照规定调整密级和划分控制使用范围，根据档案处置方案确定的归属与流向编制移交清册，移交档案。 （六）做好资产与产权变动中形成的文件材料的收集、整理、归档和移交工作。 （七）制定资产与产权变动期间的档案利用制度，做好档案利用工作。"},{"i":12,"n":"第十二条","txt":"档案处置工作结束前，档案库房、设备、装具及必要的办公用具等，应当保持原有用途不变。档案库房因各种原因无法继续使用的，应当将档案转移至符合安全保管要求的场所，明确专人管护。"},{"i":13,"n":"第十三条","txt":"国有企业资产与产权变动过程中，档案的整理、鉴定、销毁、保管、移交、数字化、数据迁移等工作所需费用，应当在资产与产权变动经费或破产经费中列支，保障档案处置工作有序开展。"},{"i":14,"n":"第十四条","txt":"国有企业合并的，合并后原各单位解散或者一方存续其他方解散的，档案由合并后的单位统一保管；合并后原各单位仍存续的，档案仍由原各单位保管。"},{"i":15,"n":"第十五条","txt":"国有企业分立的，原企业档案应当由各方协商确定其中一方保管，其他方可以利用与其业务相关的档案。"},{"i":16,"n":"第十六条","txt":"国有企业终止的，其档案的处置按照以下原则分类进行： （一）管理类档案依次归属原企业控股方、同级国家综合档案馆。 （二）基建档案、设备仪器档案随其实体归属；其实体已报废、拆除的，随企业管理类档案归属。 （三）需继续经营的产品生产和服务业务档案，归属产品和业务承接方；其他产品生产和服务业务档案由参与资产与产权变动的各方协商确定归属。 （四）科学技术研究档案（含专利、商标、专有技术等档案）按照有关法律、行政法规办理；没有规定的，由参与资产与产权变动的各方协商确定。 （五）已结清的会计档案应当同企业管理类档案归属，未结清的会计档案应当抽出移交给承接业务的单位。法律、行政法规另有规定的，依照法律、行政法规的规定办理。 （六）干部职工档案按照有关规定确定归属。 （七）无法归入以上类别的档案同企业管理类档案归属。"},{"i":17,"n":"第十七条","txt":"国有企业控制权变更为非国有企业的，管理类档案依次归属原企业控股方、同级国家综合档案馆；其他档案由参与资产与产权变动的各方参照本办法确定归属，应当保证国有资产监督管理机构和原国有企业控股方可利用原企业的全部档案。"},{"i":18,"n":"第十八条","txt":"国有企业分离办社会职能的，原承担办社会职能的单位移交地方管理或改制重组的，其档案应当随分离的单位归属；原承担办社会职能的单位终止的，参照本办法第十六条规定确定档案归属。"},{"i":19,"n":"第十九条","txt":"国有企业境外经营单位发生资产与产权变动的，按照本办法结合《企业境外档案管理办法》确定档案归属。"},{"i":20,"n":"第二十条","txt":"国有企业资产与产权变动各方如对档案归属与流向有异议，且协商无法达成一致的，可以申请由同级档案主管部门予以确定。跨地区、跨系统、跨层级的，由共同的上一级档案主管部门予以确定。"},{"i":21,"n":"第二十一条","txt":"国有企业资产与产权变动各方如存在多方档案保存需求，经协商一致，相关方可以保存档案复制件。"},{"i":22,"n":"第二十二条","txt":"涉及国家秘密或者公开后可能危及国家安全、公共安全、经济安全、社会稳定的档案，其处置应当依照有关法律、行政法规的规定。"},{"i":23,"n":"第二十三条","txt":"国有企业资产与产权变动中形成的文件材料归档范围： （一）国有企业关于资产与产权变动的申请、批复、决定、方案、通知、专家意见、可行性研究报告等文件材料。 （二）成立国有企业资产与产权变动工作机构的文件材料。 （三）国有企业资产与产权变动工作机构、负责人形成的决议、方案、报告、通知等文件材料正本、定稿和处理签报。 （四）国有企业召开关于资产与产权变动的工作会议形成的会议记录、纪要、录音、录像、照片及其他文件材料。 （五）国有企业股权变更、机构变动、资产划转等形成的章程、报告、文件、合同、协议、凭证、法律意见书等文件材料。 （六）审计、资产评估、清算等核准财务状况形成的报告、报表、编制说明、意见书等文件材料。 （七）人民法院出具的判决书、裁定书、通知书、公告、复函等文件材料。 （八）国有企业注销登记的股东会决议、清算材料、行政决定书等文件材料。 （九）涉及职工安置方案、职工安置协议、解除劳动"},{"i":24,"n":"第二十四条","txt":"国有企业资产与产权变动中形成的文件材料，应当按照本办法确定的归档范围，由专人收集整理后向资产与产权变动企业或原企业控股方档案部门移交。"},{"i":25,"n":"第二十五条","txt":"各单位应当在不影响利用的前提下，保持资产与产权变动国有企业档案的原有整理成果。"},{"i":26,"n":"第二十六条","txt":"需移交的档案应当在资产与产权变动有关工作结束后1个月内完成移交。 移交档案的单位应当按照有关规定编制档案移交清册，列明待移交档案的名称、年度、件（卷）号、保管期限、密级等内容。交接双方应当按照档案移交清册所列内容逐项查验,并由交接双方的有关负责人监督。交接完毕后,交接双方在档案移交清册上签名、盖章。档案移交清册应当一式两套，分别由交接双方保管。电子档案的移交按照国家有关规定执行。"},{"i":27,"n":"第二十七条","txt":"接收档案的单位应当妥善保管档案，落实管理责任，确保档案实体与信息安全。"},{"i":28,"n":"第二十八条","txt":"接收档案的单位应当建立健全档案利用制度，按照规定为各方及原企业职工提供利用。"},{"i":29,"n":"第二十九条","txt":"各省、自治区、直辖市档案主管部门可以根据本办法制定实施细则。"},{"i":30,"n":"第三十条","txt":"科技事业单位可以参照本办法执行。"},{"i":31,"n":"第三十一条","txt":"本办法由国家档案局负责解释，自2021年11月1日起施行。1998年3月印发的《国有企业资产与产权变动档案处置暂行办法》（档发字〔1998〕6号）同时废止"}],"chengshijianshedanganguishuyuliuxiangzanxingbanfa":[{"i":1,"n":"第一条","txt":"为了合理确定城市建设档案的归属和流向，更好地为城市建设和有关工作服务，根据《中华人民共和国档案法》和《全国档案馆设置原则和布局方案》等有关法规，制定本办法。"},{"i":2,"n":"第二条","txt":"城市建设档案是指在城市规划、建设及其管理工作中形成的应当归档保存的文字、图表、声像等各种载体的文件材料。"},{"i":3,"n":"第三条","txt":"城市建设档案产生于城市规划区内进行建设的单位（包括各类机关、团体、企业事业单位），形成于建设工程的全过程及其有关的部门（如气象、土地、环保、房地产等）。城市建设档案的归属和流向由国家档案行政管理部门统筹规划与协调。各有关部门单位根据本办法做好城市建设档案的保管、报送和接收工作。"},{"i":4,"n":"第四条","txt":"城市建设档案归属和流向的原则是： （一）符合国家有关档案归属、流向的整体规划和要求； （二）有利于城市规划、建设及其管理的需要； （三）保障档案形成单位的凭证依据和日常工作的需要。"},{"i":5,"n":"第五条","txt":"城市建设档案馆的接收范围 （一）城市勘测、规划档案 １．勘察：编制城市规划所必要的工程地质、水文地质普查及详细成果副本。 ２．测绘：编制城市规划所必要的控制测量、地形测量、摄影测量、工程测量成果副本，城市地形图和地下管线图。 城市地下管网普查、补测成果档案。 ３．规划：城市规划行政主管部门形成的经城市人民政府批准的总体规划、分区规划、详细规划和各专业规划文件材料。 ４．规划管理：城市规划行政主管部门形成的有关城市建筑管理、管线管理等文件材料。 （二）城市基础设施建筑工程档案 １．道路：城市主要道路、广场、停车场和重要公路的工程档案材料及道路图。 ２．桥涵：城市永久性桥梁、立体交叉高架路、人行过街桥（道）、重要涵洞、隧洞、隧道的工程档案材料及桥涵分布图（铁路桥涵按３•１）。 ３．排水：城市污、雨水排除及污水处理工程档案材料及管网现状图。 ４．供水：城市取水、输水、净水和配水设施档案材料及"},{"i":6,"n":"第六条","txt":"城市建设档案馆可收集城市建设、规划行政主管部门在城市建设管理中形成的有关城市建设基础资料： （一）城市历史资料包括城市历史沿革、历史文化遗迹、地名、各项建设事业和设施发展史等资料。 （二）城市自然资料包括气象、水文、地质、地震等资料。 （三）城市技术经济资料包括城市经济、人口、自然资源、环境、交通、文化教育、科研、卫生、体育、工矿、企事业的现状及发展等统计资料。 （四）有关城市建设的方针、政策、法规、计划文件资料、统计资料及设计、科研、施工等技术规程规范、专业论著等资料。"},{"i":7,"n":"第七条","txt":"产生城市建设档案的各单位，除按本办法第五条所列范围向城建档案馆报送外，应根据国家有关规定，做好本单位城市建设档案的收集、整理、保管和利用工作。"},{"i":8,"n":"第八条","txt":"城市建设档案的报送。 根据本办法所确定的范围，城市规划区内有关单位应向当地城市建设档案馆报送有关城市建设档案。凡属规划、市政公用及管理方面的，由主管部门负责报送；凡属基本建设项目（工程）方面的，由建设单位负责报送；凡属城市建设系统科研、设计、以及地下管网普查、补测等方面的，由承担任务部门或单位负责报送。"},{"i":9,"n":"第九条","txt":"城市建设档案的接收。 各大中城市城市建设档案馆依据本办法确定的范围，负责接收本城市规划区范围内有关城市建设档案，收集有关城市建设的基础资料。城市建设档案馆接收本办法范围以外的档案应报请当地档案行政管理部门批准；涉及中央主管部门驻地方单位的，由国家档案行政管理部门统筹规划、协调。"},{"i":10,"n":"第十条","txt":"城市建设档案的报送时间。 凡属新建项目（工程）应在项目（工程）竣工验收后６个月内，向城市建设档案馆报送；地下管网普查、补测应在工作结束后及时向城市建设档案馆报送；其它城市建设档案应自形成之日起５至１０年向城市建设档案馆报送。"},{"i":11,"n":"第十一条","txt":"向城市建设档案馆报送城市建设的案卷质量，由报送单位（部门）负责，按国家标准ＧＢ／Ｔ　１１８２２－８９《科学技术档案案卷构成的一般要求》进行整理。案卷（卷盒）封面和脊背可不填写，由城市建设档案统一分类、编号并填写。"},{"i":12,"n":"第十二条","txt":"本办法第五条内容中涉及工程前期管理性文件材料的原件，应保存在档案形成单位；城市建设档案馆接收副本或复制件。"},{"i":13,"n":"第十三条","txt":"城市建设档案的报送与接收应办理交换手续，明确移交档案的内容、卷（册）和页数，并有完备的签字验收手续和利用权限、保管期限等说明。"},{"i":14,"n":"第十四条","txt":"报送单位应对所报送的城市建设档案建立目录清单，并根据其变更情况（改建、扩建和补测）及时向城市建设档案馆补报有关变更内容；城市建设档案馆接到变更内容后应及时对有关文件进行修改。"},{"i":15,"n":"第十五条","txt":"开发区基本建设档案依照国家档案局、国务院特区办、国家科委联合颁布的《开发区档案管理暂行规定》执行。"},{"i":16,"n":"第十六条","txt":"城市建设档案的报送与接收由档案行政管理部门进行监督、协调。对违反本办法的单位和部门，由县以上档案行政管理部门依照《中华人民共和国行政处罚法》和《中华人民共和国档案法》给予处罚。"},{"i":17,"n":"第十七条","txt":"各地区、各城市已制定的城市建设档案馆接收档案范围的规定和内容与本办法不符的，以本办法为准。"},{"i":18,"n":"第十八条","txt":"各省、自治区、直辖市档案行政管理部门可根据本办法制定实施细则。"},{"i":19,"n":"第十九条","txt":"本办法由国家档案局负责解释。"},{"i":20,"n":"第二十条","txt":"本办法自发布之日起施行。"}],"chengshishequdanganguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范城市社区档案（以下简称社区档案）管理，根据《中华人民共和国档案法》《中华人民共和国城市居民委员会组织法》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称社区档案，是指城市社区党组织、居民委员会、社区服务机构、社区社会组织（以下简称社区各类组织）和居民在社区建设中形成的具有保存价值的各种文字、图表、声像、电子数据等不同形式和载体的历史记录。"},{"i":3,"n":"第三条","txt":"社区档案工作在业务上接受街道办事处（乡镇人民政府）以及档案行政管理部门和民政部门的监督和指导。"},{"i":4,"n":"第四条","txt":"社区党组织和居民委员会应当重视档案工作，加强组织领导，将档案工作纳入社区建设内容，促进档案工作与社区其他各项工作同步协调发展。"},{"i":5,"n":"第五条","txt":"社区档案工作经费从社区的办公经费中列支，并应当满足实际工作的需要。"},{"i":6,"n":"第六条","txt":"社区党组织或者居民委员会应当指定人员管理本社区各类档案,有条件的地方可以设立综合档案室。 档案管理人员应当经过档案专业知识培训，调离工作岗位时应当在离职前办理档案交接手续。"},{"i":7,"n":"第七条","txt":"社区综合档案室或者档案管理人员负责宣传、贯彻和执行党和国家有关档案工作的法律法规和标准规范，指导、监督本社区文件材料的归档、整理和移交工作。"},{"i":8,"n":"第八条","txt":"社区档案由社区综合档案室或者档案管理人员集中统一管理，任何单位和个人不得据为己有或者擅自销毁。"},{"i":9,"n":"第九条","txt":"社区建设中形成的文件材料可以分为文书类、科技类、会计类等三个大类，具体的归档范围和保管期限参照本办法附件。"},{"i":10,"n":"第十条","txt":"社区文件材料的归档，应当符合以下要求： （一）归档的文件材料应当齐全、完整、排列有序；装订结实、整齐；备考表填写真实、清楚；归档文件目录或者卷内文件目录明晰、准确； （二）归档的文件材料中有照片或者复印件的，应当图文清晰； （三）归档时间： 文书材料于次年6月底前归档； 科技文件材料在科技活动结束后1个月内归档； 会计材料由会计部门在会计年度终了后保管1年，于次年3月底前归档； 声像材料在活动结束或者办理完毕后随时归档； 实物材料及时归档； 电子文件按照《电子文件归档与管理规范》（GB/T18894）和《电子文件归档光盘技术要求和应用规范》(DA/T38)的要求整理。"},{"i":11,"n":"第十一条","txt":"社区档案按照下列规则进行分类编号： （一）文书档案按照年度——问题（社区党建、居民自治、社区管理、社区服务、社区治安等）进行分类，参照《归档文件整理规则》，以件为单位，按年度——问题——保管期限排列编号； （二）科技档案中的基建档案按照工程项目分类整理，按照项目——时间排列编号；设备仪器档案按照型号分类整理，按照型号——时间排列编号； （三）会计档案按照年度——类别（报表、账簿、凭证、其他）分类整理并排列编号。"},{"i":12,"n":"第十二条","txt":"社区综合档案室或者档案管理人员应当设立专室或者专柜保管档案，采取有效的防火、防盗、防高温、防潮、防光、防尘、防鼠、防虫、防磁等措施，确保档案的完整与安全。"},{"i":13,"n":"第十三条","txt":"档案管理人员应当定期对档案及其保管状况进行全面检查，并形成安全检查记录；如有破损、霉变、虫蛀、褪色等现象时，应当及时修补、复制或者进行其他技术处理。 对声像档案和电子档案，要定期检查信息记录的安全性，确保档案可读可用；有条件的地方要及时对声像档案进行数字化转化，以利于长期使用。"},{"i":14,"n":"第十四条","txt":"社区综合档案室或者档案管理人员应当建立档案统计制度，对档案的收进和移出、保管数量、借阅和利用效果、销毁等情况，进行及时、准确的统计。"},{"i":15,"n":"第十五条","txt":"社区综合档案室或者档案管理人员应当建立健全档案利用制度，为档案利用创造条件，简化手续，提供方便。 利用档案时应当按照规定办理手续，并及时做好利用效果登记。 档案管理人员应当认真检查归还档案，如发现有短缺、涂改、污损情况，要及时报告并追查。"},{"i":16,"n":"第十六条","txt":"社区应当组织成立档案鉴定工作小组，对已到期档案及时进行鉴定。 鉴定工作小组由社区档案管理人员和形成档案的组织的人员（或者居民代表）组成，鉴定后应当形成档案鉴定报告。对失去保存价值的档案，应当清点核对并编制档案销毁清册，经过必要的审批手续后按照规定销毁。 禁止擅自销毁档案。档案销毁清册应当永久保存。"},{"i":17,"n":"第十七条","txt":"社区档案应当依法保持齐全完整，不得随意将社区档案拆散、重新组合。"},{"i":18,"n":"第十八条","txt":"社区综合档案室或者档案管理人员应当围绕社区中心工作和居民利用需求，加强档案信息资源的开发利用，积极开展档案编研工作。"},{"i":19,"n":"第十九条","txt":"社区档案管理应当积极采用计算机等先进技术，逐步实现档案管理的信息化、现代化。"},{"i":20,"n":"第二十条","txt":"涉及国家秘密、商业秘密和个人隐私等内容的档案的保管、利用，应当按照国家有关法律法规规定办理。"},{"i":21,"n":"第二十一条","txt":"违反国家有关规定，对档案有损毁、丢失以及出卖、涂改、伪造、泄密等情况的，应当依法追究相关人员责任。构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"各省（自治区、直辖市）、新疆生产建设兵团档案行政管理部门商同级民政部门，可以结合当地实际情况制定本办法的实施细则。"},{"i":23,"n":"第二十三条","txt":"本办法由国家档案局和民政部负责解释。"},{"i":24,"n":"第二十四条","txt":"本办法自2016年1月1日起施行。 城市社区文件材料归档范围和保管期限表"}],"kaifaliyongkexuejishudanganxinxiziyuanzanxingbanfa":[{"i":1,"n":"第一条","txt":"为大力开发利用科学技术档案信息资源，充分发挥科学技术档案在社会主义现代化建设中的作用，根据《中华人民共和国档案法》和《科学技术档案工作条例》制定本办法。"},{"i":2,"n":"第二条","txt":"科学技术档案(以下简称科技档案)是国家重要的科学技术信息资源，各有关单位、部门应切实做好这一资源的开发利用，为加速科技信息交流，促进科学技术成果的推广应用服务，为深化改革、促进经济建设和科学技术发展服务。"},{"i":3,"n":"第三条","txt":"开发科技档案信息资源，是针对本单位及社会有关方面的需求，通过各种方式对科技档案中储存的科学技术信息进行发掘，使其尽快转化为现实生产力的重要工作，是提高科技档案工作经济效益的有效途径。"},{"i":4,"n":"第四条","txt":"开发利用科技档案信息资源是档案提供利用工作的拓展和深化。各有关档案部门应面向科研、设计、生产和管理，面向引进技术的消化吸收及我国产品、技术的出口；积极参与技术市场和信息市场，促进横向经济联系及对外经济交流；为各级领导的计划、规划、预测、决策及可行性研究提供必要的科技档案信息。"},{"i":5,"n":"第五条","txt":"开发利用科技档案信息资源可根据不同情况和条件，采取不同的形式： 一、开架阅览。对降密、解密的科技档案(副本)开辟内部阅览室，开架服务，使科技档案直接与利用者见面。 二、信息报道、交流。在做好档案著录、建立起有效的检索系统基础上，可对档案中储存的新理论、先进技术、工艺、方法等信息，以题(目)录、简介、文摘等形式，定期或不定期地在行业、地区协作组织内进行交流、宣传、介绍。 三、科技档案信息加工。对科技档案、原始资料、数据进行归纳、综合、计算、分析、翻译、研究加工。 1.提供二次、三次文献服务，如对档案信息加工后形成的专题汇编、专业年鉴、专用图集、专项手册、大事记、大全等。 2.围绕某一专题(课题)或根据某方面工作的需要，对原始数据进行综合、归纳、分析、筛选，提供反映规律性、本质性的信息。 3.做好引进项目科技档案资料的翻译、整理、汇编、加工，为引进技术的消化吸收服务。 四、配合业务技术部门"},{"i":6,"n":"第六条","txt":"开发利用科技档案信息资源要加强横向联系，促进信息交流。各地区、各有关部门要积极创造条件，逐步建立起科技档案目录中心，承担或负责组织、协调、指导地区及行业的科技档案和目录信息交流。"},{"i":7,"n":"第七条","txt":"要建立开发利用效果反馈记录。档案管理部门应建立服务跟踪记录，收集利用效果信息，总结开发经验，使开发利用形式和内容更加适应我国经济建设、科学技术发展的需要。"},{"i":8,"n":"第八条","txt":"开发利用科技档案信息资源要保证国家科学技术机密的安全。任何单位、个人都要严格遵守《科学技术保密条例》及国家其他有关保密的规定。既要坚持内外有别，又不妨碍科技档案信息交流。"},{"i":9,"n":"第九条","txt":"随着科学技术的进步，各有关部门要及时做好科技档案的降密解密工作。档案降密解密经鉴定后，必须报上级主管部门批准，方能开发利用。 国家经济、技术、军事科学研究发展的基本情况资料、数据、观、探、监测记录，各类普查统计记录及分析研究报告，凡涉及国家安全和战略决策、布局、尖端技术、攻关项目等重大科技机密的，要报经主管部门批准后，方能开发利用。"},{"i":10,"n":"第十条","txt":"信息开发与专利保护都是为了加速科技成果及时、有效、合法地推广应用，促进科技成果向生产转化。任何单位、个人不得借口申请专利而不向档案部门移交应该归档(属于职务发明)的有关文件材料，档案部门有责任在其申请专利的过程中为其保密，对需要进行技术交流、开发或参考使用该项成果的科技档案，须经专利申请人(或单位)同意。专利申请获准成为技术商品后，除技术诀窍在专利保护期内应保密外，档案部门应依照《中华人民共和国专利法》的规定，积极为其宣传。对一些不授专利的科技成果，及获得国家、省、部级科技进步奖的成果，其档案管理参照本办法第八、九两条规定办理。"},{"i":11,"n":"第十一条","txt":"档案部门应与科技情报、资料部门协调工作，共同为企事业科研、生产、管理和经营决策服务。"},{"i":12,"n":"第十二条","txt":"有偿使用原则： 一、各级领导机关因计划、规划、预测、决策所需的科技档案资料应无偿提供或只收工本费。 二、对社会公益性服务(指社会团体、社会服务保障部门，如气象、水文、地震预报及自然灾害抢救等需要)及列入国家发展计划的社会公益事业，应无偿提供使用或只收工本费。但利用者不得将档案及复印资料转让其他单位或进行有偿咨询、营利等活动，否则应承担经济责任及法律责任。 三、本单位工作利用可不收费；外单位需要利用原汇交(总)、上报、移交的科技档案，只能收取工本费。 四、经济效益性服务(指外单位利用开发成果是为生产经营或研究、设计参考，从而获得商品化成果及一定的经济效益)应按成本费、开发转让费收取费用。"},{"i":13,"n":"第十三条","txt":"收费标准：可根据科技档案所反映成果的技术水平，先进程度，根据开发劳动的难易程度和工作量，以及利用档案资料可能取得的经济效益的大小，本着有利于成果推广、促进生产发展的原则，由主管部门制定。对中外合资(合作)或外商独资企业所需我方属于测量、勘察、观、探、监测记录所形成的档案资料(如地质、水文、气象、测绘及海洋、石油勘探等)，收费不应低于其记录成果形成时成本的50%。"},{"i":14,"n":"第十四条","txt":"收费方法：档案部门配合技术部门参与技术市场、信息市场活动外，独立档案部门还可参照技术合同的方式来规定开发方与受让方(使用方)的义务、费用及违约处理办法。开发利用一旦订立合同，即可在《中华人民共和国技术合同法》的保护下，解决开发中费用、收益及其他有关问题。"},{"i":15,"n":"第十五条","txt":"费用管理：开发利用科技档案信息资源的收入(包括计算、汇编、照排、复印、翻译、绘图、晒图及对档案资料二、三次编研加工后直接用于转让、咨询各种服务方式所得)扣除成本后的净收入，企业视同技术转让收入，按财政部(1986)财工字105号文(十二条)规定办理，事业单位纳入预算管理。按规定留给企事业单位的收入，其主要部分应用于改善本单位档案信息现代化管理的条件，弥补档案事业费的不足。"},{"i":16,"n":"第十六条","txt":"对于开发利用科技档案信息资源做出显著贡献的集体和个人，应当比照直接从事研究科技人员，根据有关规定给予表彰和奖励。"},{"i":17,"n":"第十七条","txt":"对违反上述有关规定的应按照国家政策法规追究行政和法律责任。"},{"i":18,"n":"第十八条","txt":"本办法适用于全民所有制企业、事业单位。有关单位可结合具体情况制定实施细则。"},{"i":19,"n":"第十九条","txt":"本办法自发布之日起施行。"}],"kaifaqudanganguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为加强开发区档案的管理和利用工作，更好地为开发区各项工作服务，根据《中华人民共和国档案法》及有关法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于国家级经济技术开发区、高新技术产业开发区、保税区、边境经济合作区和国家旅游度假区（以下简称开发区）。"},{"i":3,"n":"第三条","txt":"开发区档案是指开发区内各单位在各项活动中形成的具有利用和保存价值的各种文字、图表、声像等不同形式的文件材料。"},{"i":4,"n":"第四条","txt":"开发区档案工作是开发区工作和国家档案工作的组成部分。开发区管委会、党（工）委、开发总公司（以下简称开发区管理机构）应在当地政府的指导下，加强对开发区档案工作的管理，列入工作计划，维护档案的完整、准确与安全，便于利用档案。"},{"i":5,"n":"第五条","txt":"开发区管理机构应当明确分管档案工作的领导人，确定管理档案工作的部门或人员，建立健全开发区的档案工作。 开发区档案工作在开发区所在城市档案行政管理部门和上级档案行政管理部门的监督和指导下进行。"},{"i":6,"n":"第六条","txt":"开发区管理机构必须建立总档案室，具备条件的应建立档案馆，保管开发区需要永久和长期保存的档案及有关资料；开发区各入区单位应当建立档案室，统一管理本单位的档案。"},{"i":7,"n":"第七条","txt":"开发区各单位档案部门应配备适应档案工作需要的专、兼职档案人员。 开发区档案工作人员应当忠于职守，遵守纪律，具有专业技术技能，取得职业资格证书。 对在档案收集、整理、保护和技术利用等方面成绩显著的单位或者个人应给予奖励。对造成档案损失的要追究当事人的责任。"},{"i":8,"n":"第八条","txt":"开发区管理机构档案工作管理部门的职责： 1．贯彻执行国家有关档案工作的法律、法规和方针政策。 2．建立健全开发区档案工作的规章制度。 3．负责开发区总档案室（或档案馆）的业务建设,并确定其接收档案的范围。 4．负责对全区各单位的档案工作进行协调、监督和指导。"},{"i":9,"n":"第九条","txt":"开发区各单位应当将文件材料的形成、收集、立卷归档工作列入文书部门和业务部门的职责范围以及有关人员的岗位责任，并形成制度。 归档文件材料必须完整、准确、保持有机联系，反映工作全过程。"},{"i":10,"n":"第十条","txt":"开发区各单位档案部门应当制定文件材料的归档范围和档案的保管期限。"},{"i":11,"n":"第十一条","txt":"开发区各单位要根据国家有关规定，加强对基本建设项目档案的管理，建立和健全基本建设项目竣工文件的编制和档案验收制度。 开发区基础设施及进区项目建设，在签订协议、合同时，应当明确各方在编制和移交竣工档案方面的责任、费用以及移交范围、要求和时间。"},{"i":12,"n":"第十二条","txt":"开发区各单位应于每年上半年完成上一年度形成的应归档文件材料的立卷，并向档案室归档；基本建设项目应在竣工验收后六个月内，完成文件材料的组卷和向档案室归档工作。"},{"i":13,"n":"第十三条","txt":"开发区各单位档案部门原则上执行国家颁布的各项档案业务建设标准、规范，并依据有关规定，建立健全档案的收集、整理、保管、统计、鉴定、保密和利用等制度。"},{"i":14,"n":"第十四条","txt":"开发区各单位档案部门应当建设和配置必须的档案保管设施，确保档案的安全，档案馆库房应符合《档案馆建筑设计规范》和《档案库房技术管理暂行规定》的要求，逐步采用先进技术，实现档案管理现代化。"},{"i":15,"n":"第十五条","txt":"开发区各单位档案部门要注重和加强档案信息的编研、咨询等开发利用工作，及时有效地提供档案资料信息。"},{"i":16,"n":"第十六条","txt":"开发区管理机构各部门及直属单位形成的档案，应在5年内向开发区档案馆或总档案室移交；区内基本建设项目竣工档案在工程竣工验收后六个月内，建设单位应向开发区档案馆或总档案室报送竣工档案。 开发区管理机构应及时向所在城市报送开发区总体规划和与城市衔接的道路、地下管网图。 开发区撤销机构和部门的档案应向开发区档案馆或总档案室移交。"},{"i":17,"n":"第十七条","txt":"各省、自治区、直辖市开发区主管部门和档案行政管理部门可根据本规定制定细则。"},{"i":18,"n":"第十八条","txt":"本规定由国家档案局负责解释。"},{"i":19,"n":"第十九条","txt":"本规定自发布之日起施行。"}],"jiguanwenjiancailiaoguidangfanweihewenshudanganbao5acac2":[{"i":1,"n":"第一条","txt":"为便于各级党政机关和人民团体（以下统称机关）正确界定文件材料归档范围，准确划分档案保管期限，使所保存的档案既能反映机关主要职能活动情况，维护其历史面貌，又便于保管和利用，根据《中华人民共和国档案法》、《中华人民共和国档案法实施办法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定中的机关文件材料是指机关在其工作活动过程中形成的各种门类和载体的历史记录。"},{"i":3,"n":"第三条","txt":"机关文件材料归档范围是： （一）反映本机关主要职能活动和基本历史面貌的，对本机关工作、国家建设和历史研究具有利用价值的文件材料； （二）机关工作活动中形成的在维护国家、集体和公民权益等方面具有凭证价值的文件材料； （三）本机关需要贯彻执行的上级机关、同级机关的文件材料；下级机关报送的重要文件材料； （四）其他对本机关工作具有查考价值的文件材料。"},{"i":4,"n":"第四条","txt":"机关文件材料不归档范围是： （一）上级机关的文件材料中，普发性不需本机关办理的文件材料，任免、奖惩非本机关工作人员的文件材料，供工作参考的抄件等； （二）本机关文件材料中的重份文件，无查考利用价值的事务性、临时性文件，一般性文件的历次修改稿、各次校对稿，无特殊保存价值的信封，不需办理的一般性人民来信、电话记录，机关内部互相抄送的文件材料，本机关负责人兼任外单位职务形成的与本机关无关的文件材料，有关工作参考的文件材料； （三）同级机关的文件材料中，不需贯彻执行的文件材料，不需办理的抄送文件材料； （四）下级机关的文件材料中，供参阅的简报、情况反映，抄报或越级抄报的文件材料。"},{"i":5,"n":"第五条","txt":"凡属机关归档范围的文件材料，必须按有关规定向本机关负责档案工作的部门移交，实行集中统一管理，任何个人不得据为己有或拒绝归档。"},{"i":6,"n":"第六条","txt":"机关文书档案的保管期限定为永久、定期两种。定期一般分为30年、10年。"},{"i":7,"n":"第七条","txt":"永久保管的文书档案主要包括： （一）本机关制定的法规政策性文件材料； （二）本机关召开重要会议、举办重大活动等形成的主要文件材料； （三）本机关职能活动中形成的重要业务文件材料； （四）本机关关于重要问题的请示与上级机关的批复、批示，重要的报告、总结、综合统计报表等； （五）本机关机构演变、人事任免等文件材料； （六）本机关房屋买卖、土地征用，重要的合同协议、资产登记等凭证性文件材料； （七）上级机关制发的属于本机关主管业务的重要文件材料； （八）同级机关、下级机关关于重要业务问题的来函、请示与本机关的复函、批复等文件材料。"},{"i":8,"n":"第八条","txt":"定期保管的文书档案主要包括： （一）本机关职能活动中形成的一般性业务文件材料； （二）本机关召开会议、举办活动等形成的一般性文件材料； （三）本机关人事管理工作形成的一般性文件材料； （四）本机关一般性事务管理文件材料； （五）本机关关于一般性问题的请示与上级机关的批复、批示，一般性工作报告、总结、统计报表等； （六）上级机关制发的属于本机关主管业务的一般性文件材料； （七）上级机关和同级机关制发的非本机关主管业务但要贯彻执行的文件材料； （八）同级机关、下级机关关于一般性业务问题的来函、请示与本机关的复函、批复等文件材料； （九）下级机关报送的年度或年度以上计划、总结、统计、重要专题报告等文件材料。"},{"i":9,"n":"第九条","txt":"机关形成的人事、基建、会计及其他专门文件材料的归档范围和档案保管期限，按国家有关规定执行。"},{"i":10,"n":"第十条","txt":"机关对应归档电子文件的元数据、背景信息等要进行相应归档。 机关应归档纸质文件材料中，有文件发文稿纸、文件处理单的，应与文件正本、定稿一并归档。"},{"i":11,"n":"第十一条","txt":"机关联合召开会议、联合行文所形成的文件材料原件由主办机关归档，其他机关将相应的复制件或其他形式的副本归档。"},{"i":12,"n":"第十二条","txt":"各机关应根据本规定，结合本机关职能和各部门工作实际，编制本机关的文件材料归档范围和文书档案保管期限表，经同级档案行政管理部门审查同意后执行。 有垂直领导关系的中央、国家机关应依据本规定，结合本系统工作实际，编制本系统的文件材料归档范围和文书档案保管期限表，并经国家档案局审查同意后执行。"},{"i":13,"n":"第十三条","txt":"在编制本机关或本系统文件材料归档范围和文书档案保管期限表时，应全面分析和鉴别本机关或本系统文件材料的现实作用和历史作用，准确界定文件材料的归档范围和划分档案保管期限。"},{"i":14,"n":"第十四条","txt":"本规定适用于各级党政机关和人民团体。军队系统、民主党派、企业事业单位可参照执行。"},{"i":15,"n":"第十五条","txt":"本规定自颁布之日起施行，1987年颁发的《国家档案局关于机关档案保管期限的规定》和《机关文件材料归档和不归档的范围》同时废止。 附件：文书档案保管期限表 1本级党的代表大会、人民代表大会、政治协商会议，工会、共青团、妇联代表大会的文件材料 1.1请示、批复、通知、名单、议程、报告、领导人讲话、选举结果、讨论通过的文件、决议、纪要、公报、主席团会议记录等文件材料（永久） 1.2大会发言，人大代表建议和意见、人大议案及答复，政协委员提案及办理结果，简报，快报（永久） 1.3重要的贺信、贺电，筹备工作、选举过程中形成的文件，小组会议记录、会议服务机构的计划、总结等文件材料（30年） 1.4讨论未通过的文件（10年） 2本级党委、人民代表大会、政治协商会议、纪律检查委员会、共青团、工会、妇联的常委会、执委会、主席团、全体委员会会议，政府常务会、办公会议的文件材料 2.1公报、决议、决定、记录、"}],"jiguandanganguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强各级党和国家机关、人民团体（以下统称机关）档案工作，推进机关档案科学、规范管理，丰富国家档案资源，为各项工作提供有效服务，根据《中华人民共和国档案法》《机关档案工作条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称的机关档案，是指机关在公务活动中形成的，对国家和社会有查考、利用和保存价值的各种形式、各种载体的信息记录。"},{"i":3,"n":"第三条","txt":"机关档案工作是档案工作开展的基础，是国家档案事业的重要组成部分。 机关档案工作是机关不可缺少的基础性工作，是推进依法行政、促进科学决策、提高治理水平的必要条件，是保护单位和个人合法权益、维护机关历史真实面貌的一项重要工作。"},{"i":4,"n":"第四条","txt":"机关档案工作实行统一领导、分级管理。 国家档案行政管理部门负责全国机关档案工作的统筹规划、组织协调、统一制度，负责中央和国家机关档案工作的监督、指导和检查。地方档案行政管理部门在上级档案行政管理部门指导下，负责本行政区域内机关档案工作的统筹协调、制度建设，负责本行政区域内机关档案工作的监督、指导和检查。 档案行政管理部门履行检查职责时，以进入相关场所检查，询问有关人员，查阅、复制有关档案资料等方式开展。 中央和地方专业主管机关应当根据本专业的管理体制，在档案行政管理部门指导下对本系统和直属单位的档案工作进行监督、指导。中央和地方专业主管机关进行监督、指导时，应当遵循统一领导、分级管理原则。"},{"i":5,"n":"第五条","txt":"机关的全部档案应当集中、统一管理。 机关档案管理应当维护档案的真实、完整、可用和安全，便于检索、利用和开发。"},{"i":6,"n":"第六条","txt":"机关应当加强对档案工作的组织领导，将档案工作纳入整体规划、年度工作计划和考核体系，与业务工作同步部署、同步实施、同步发展。 档案工作所需的基础设施配备和维护经费，档案日常管理工作经费，档案信息化建设经费，档案宣传、培训等其他经费应当列入机关年度财政预算。"},{"i":7,"n":"第七条","txt":"机关应当建立由机关分管档案工作的单位负责人、办公厅（室）（或承担办公厅（室）职能的部门，下同）及相关部门负责人组成的档案工作协调机制，协调处理本机关、本系统档案工作重大事务和重要事项。"},{"i":8,"n":"第八条","txt":"机关应当按规定设立档案工作机构。不具备档案工作机构设立条件的机关，应当指定档案工作负责部门。档案工作负责部门的名称应当反映档案工作属性。 经同级档案行政管理部门同意，办公地点相对集中且条件成熟的县级或形成档案数量较少的多个机关可以成立联合档案工作机构，对相应机关的档案进行集中管理。"},{"i":9,"n":"第九条","txt":"机关档案工作机构或档案工作负责部门（以下简称机关档案部门）应当配备与工作量相匹配的专职档案工作人员，具体承担机关档案业务工作。机关文书或业务部门应当指定人员，承担相应部门文件材料的收集、整理和归档工作。机关应当建立以机关档案部门为中心，由相关人员组成的机关档案工作网络。 县级或形成档案数量较少的机关可以综合考虑工作量等情况，配备适当数量的专（兼）职档案工作人员。"},{"i":10,"n":"第十条","txt":"机关档案工作的基本任务是： （一）贯彻执行档案工作的法律法规和方针政策，建立健全档案工作规章制度，并将规范本单位、本系统档案管理的基本制度报档案行政管理部门备案； （二）制定并组织实施档案工作发展规划或计划； （三）对机关各种文件材料的形成、积累和归档工作进行监督和指导，对所属机构的档案工作进行监督和指导； （四）负责管理机关的全部档案并提供利用，协助做好机关政府信息公开工作； （五）负责机关档案信息化工作并统筹机关及所属机构档案信息一体化工作，推动传统载体档案数字化和电子文件、电子档案规范管理； （六）接受档案行政管理部门监督、指导和检查，执行年度报告制度，定期向同级国家综合档案馆移交档案； （七）负责组织档案业务交流和档案工作人员培训，开展档案宣传、教育活动； （八）对档案工作中取得突出成绩的部门或个人，向机关提出表彰奖励建议；对违反档案管理要求的部门或个人，向机关提出处理建议。"},{"i":11,"n":"第十一条","txt":"机关通过档案购买服务方式辅助实现档案工作基本任务的，应当严格限定社会化服务范围，严格审核服务供方的信息安全保障能力和业务资质，并接受档案行政管理部门监督、指导和检查。 机关档案业务社会化服务限于档案整理、传统载体档案数字化、纸质档案数字复制件全文识别、电子档案管理技术支持等辅助性工作。社会化服务应当符合《档案服务外包工作规范》（DA/T 68）规定。"},{"i":12,"n":"第十二条","txt":"档案工作人员应当为机关正式在编人员，且政治可靠、遵纪守法、忠于职守，具备胜任岗位要求的工作能力。 档案工作人员应当熟悉机关工作，具备档案管理、信息管理等相关知识背景，并定期参加业务培训。 不具备前述知识背景的档案工作人员，应当经过相关专业知识和技能培训。"},{"i":13,"n":"第十三条","txt":"档案工作人员调离岗位或退休的，应当在离岗前办好交接手续。涉密档案工作人员的调离应当按照国家有关保密法律法规执行。"},{"i":14,"n":"第十四条","txt":"机关应当分别设置档案办公用房、整理用房、阅览用房和档案库房，并根据工作需要设置展览用房、档案数字化用房、服务器机房等。 档案库房应当根据载体类型分别设置，不具备条件的应当根据载体类型分区设置。 县级或形成档案数量较少的机关设置库房以外其他档案用房时，可以按照办公、整理、阅览等基本功能分区设置。"},{"i":15,"n":"第十五条","txt":"档案办公用房面积按照《党政机关办公用房建设标准》执行。 阅览用房面积应当满足不同类型档案阅览需求，适应涉密档案与非涉密档案分区阅览的需要。 档案库房面积应当满足机关档案法定存放年限需要，使用面积按（档案存量+年增长量×存放年限）×60m2/万卷（或10万件）测算。档案数量少于2500卷（或25000件）的，档案库房面积按15m2测算。 整理用房、展览用房、档案数字化用房、服务器机房等用房面积应当满足业务开展需要。"},{"i":16,"n":"第十六条","txt":"档案用房宜集中布置，自成一区。 档案办公用房选址应当便于档案库房管理。档案库房选址应当防潮、防火、避免阳光直射，利于档案保护。 档案库房不应设置在地下或顶层，地处湿润地区的还不宜设置在首层。档案库房不得毗邻水房、卫生间、食堂（厨房）、变配电室、车库等可能危及档案安全的用房。"},{"i":17,"n":"第十七条","txt":"档案办公用房建筑设计应当符合《办公建筑设计规范》（JGJ 67）规定，整理用房、阅览用房建筑设计应当符合《档案馆建筑设计规范》（JGJ 25）规定。 档案库房内不得设置其他用房和明火设施，不应设置除消防以外的给水点，其他给水排水管道不应穿越库房。档案库房的装具布置、门窗设置应当符合《档案馆建筑设计规范》（JGJ 25）规定。"},{"i":18,"n":"第十八条","txt":"档案库房应当根据需要配备符合国家规定的密闭五节柜、密集架、光盘柜、底图柜等档案装具，不得采用木质柜、玻璃门柜等装具。档案整理台、档案梯、移动置物架、档案盒、装订用品等配备应当满足工作需要。 档案库房配备的档案装具应当与档案库楼面均布活荷载标准值相匹配。库房采用密集架的，楼面均布活荷载标准值不应小于8kN/m2或按档案装载情况相应增加。"},{"i":19,"n":"第十九条","txt":"档案库房应当配备温湿度监测调控系统，安装漏水报警设备。档案库房不得使用电阻丝加热、电热油汀及以水、汽为热媒的采暖系统。 保存重要档案或具备条件的，应当安装恒温恒湿设备，必要时可配备通风换气、空气净化设备。"},{"i":20,"n":"第二十条","txt":"档案库房应当配备消防系统。根据档案重要程度和载体类型的不同，可以选择采用洁净气体、惰性气体或高压细水雾灭火设备。档案库房应当安装甲级防火门，配备火灾自动报警设备。"},{"i":21,"n":"第二十一条","txt":"档案库房应当安装全封闭防盗门窗、遮光阻燃窗帘、防护栏等防护设施，可以选择设置智能门禁识别、红外报警、视频监控、出入口控制、电子巡查等安全防范系统。整理用房、阅览用房、档案数字化用房应当设置视频监控设备。"},{"i":22,"n":"第二十二条","txt":"机关应当按照信息化要求，建设或配备能够满足库房现代化管理、档案数字化、电子文件及电子档案管理需求的基础设施设备。智能库房管理基础设施设备应当满足温湿度调控、漏水监测、消防报警、安全防范、视频监控等系统集成管理以及其他智能管理需要。档案数字化、电子文件及电子档案管理基础设施设备应当符合本规定第五章要求。 县级或形成档案数量较少的机关按照本规定第十九条至第二十二条配备基础设施设备的，应当满足温湿度调控、消防、安防和信息化工作的基本需求。"},{"i":23,"n":"第二十三条","txt":"机关档案包括： （一）文书、科技（科研、基建、设备）、人事、会计档案； （二）机关履行行业特有职责形成的专业档案； （三）照片、录音、录像等音像档案； （四）业务数据、公务电子邮件、网站信息、社交媒体档案； （五）印章、题词、奖牌、奖章、证书、公务礼品等实物档案； （六）其他档案。 前款（一）（二）（三）项包含传统载体档案和电子档案两种形式。电子档案与传统载体档案具有同等效力。"},{"i":24,"n":"第二十四条","txt":"机关全部档案构成一个全宗。机关隶属关系、名称发生变化但工作性质和主要业务范围未变化的，维持原全宗不变。 机关应当建立并定期完善全宗卷。全宗卷应当包含全宗背景、档案状况、工作制度、管理记录等内容，编制要求按照《全宗卷规范》（DA/T 12）执行。"},{"i":25,"n":"第二十五条","txt":"机关档案管理应当做到收集齐全完整，整理规范有序，保管安全可靠，鉴定准确及时，利用简捷方便，开发实用有效。 涉及国家秘密档案的管理应当符合保密管理的相关规定。"},{"i":26,"n":"第二十六条","txt":"机关履行职责过程中应当按照有关程序和要求形成归档文件材料。机关办公自动化和其他业务系统应当支持形成符合要求的归档文件材料。 文件材料形成时，应当采用耐久、可靠、满足长期保存需求的记录载体和记录方式。 归档文件材料应当真实、准确、系统，文件材料组件齐全、内容完整。"},{"i":27,"n":"第二十七条","txt":"机关文书或业务部门应当及时收集形成的归档文件材料，交本部门指定人员保管。下列文件材料应当纳入收集范围。 机关在日常公务活动中形成的归档文件材料；机关设立临时机构处理专项工作、处置突发事件、举办重要活动等形成的归档文件材料；机关承担重大建设项目、重大科研课题等形成的归档文件材料；机关所属机构撤销形成的归档文件材料；机关向社会和个人征集的、与机关有关文件材料等。"},{"i":28,"n":"第二十八条","txt":"机关应当编制本单位文件材料归档范围和档案保管期限表，经同级档案行政管理部门审查同意后施行。机关内部机构或工作职能发生变化时应当及时修订，经重新审查同意后施行。 文件材料归档范围和档案保管期限表应当全面、系统反映机关主要职能活动和基本历史面貌。人事、会计文件材料的归档范围和档案保管期限从其专门规定。 机关所属机构文件材料归档范围和档案保管期限表报机关审查同意后施行。"},{"i":29,"n":"第二十九条","txt":"文书档案的收集范围按照《机关文件材料归档范围和文书档案保管期限规定》制定执行。 会计、科研、基建档案收集范围应当分别符合《会计档案管理办法》、《科学技术研究课题档案管理规范》（DA/T 2）、《建设项目档案管理规范》（DA/T 28）及《国家电子政务工程建设项目档案管理暂行办法》规定。 照片档案的收集范围应当符合《照片档案管理规范》（GB/T 11821）和《数码照片归档与管理规范》（DA/T 50）规定。 其他门类档案收集范围按照国家相关规定执行。"},{"i":30,"n":"第三十条","txt":"电子文件应当连同元数据一并收集。收集的元数据应当符合《数字档案室建设指南》、《电子文件归档与电子档案管理规范》（GB/T 18894）、《文书类电子文件元数据方案》（DA/T 46）、《照片类电子档案元数据方案》（DA/T 54）、《录音录像类电子档案元数据方案》（DA/T 63）等规定。"},{"i":31,"n":"第三十一条","txt":"机关应当按照本规定第二十三条制定统一的档案分类方案。不同门类、载体或形式的档案的分类方法应当协调呼应，便于档案的统一管理和利用。分类方案一经确定，应当保持一致，不得随意变动。 机关档案分类方案一般采用年度、机构（问题）、保管期限等分类项进行复式分类，有专门规定的，从其规定。"},{"i":32,"n":"第三十二条","txt":"机关档案整理应当遵循文件材料的形成规律，保持文件材料之间的有机联系，区分不同价值，便于保管和利用，逐步推进卷件融合管理。 文书档案、照片档案、录音档案、录像档案、实物档案一般以件（张）等为单位进行整理。科技档案、人事档案、会计档案一般以卷为单位进行整理。其他门类档案根据需要以卷或件为单位进行整理。整理方法分别按照相应要求执行。"},{"i":33,"n":"第三十三条","txt":"机关档案应当逐卷或逐件编制档号。档号应当指代单一，体现档案来源、档案门类、整理分类体系和排列顺序等档案基本属性。档号结构应当符合《档号编制规则》（DA/T 13）、《归档文件整理规则》（DA/T 22）和《数字档案室建设指南》要求，不同载体或形式的档号编制方法应当协调呼应。 机关档案门类宜按照文书（WS）、科技（KJ）、人事（RS）、会计（KU）、专业（ZY）、照片（ZP）、录音（LY）、录像（LX）、业务数据（SJ）、公务电子邮件（YJ）、网站信息（WZ）、社交媒体（MT）、实物档案（SW）设置一级门类代码，按照科研（KJ·KY）、基建（KJ·JJ）、设备（KJ·SB）设置科技档案二级门类代码。专业档案按照《国家基本专业档案目录》规定设置二级门类代码。"},{"i":34,"n":"第三十四条","txt":"机关档案应当编制检索工具，满足手工检索和计算机检索需要。 机关档案应当按照《档案著录规则》（DA/T 18）进行著录。传统载体照片、录音、录像档案和实物档案应当详细著录背景、人物、来源等信息。档案著录应当与目录编制、元数据收集等工作和要求协调对应。"},{"i":35,"n":"第三十五条","txt":"机关档案经文书或业务部门整理完毕后，应当在第二年6月底前向机关档案部门归档；采用办公自动化或其他业务系统的，应当随办随归。归档时间有特殊规定的，从其规定。 归档时交接双方根据归档目录清点核对，并履行交接手续。机关档案实现随办随归的，还应当按规定履行登记手续，记录电子文件归档过程元数据。 任何部门和人员不得将应归档材料据为己有或拒绝归档。"},{"i":36,"n":"第三十六条","txt":"归档文件材料应当为原件。电子文件需要转换为纸质文件归档的，若电子文件已经具备电子签名、电子印章，且电子印章按照规定转换为印章图形的，纸质文件不需再行实体签名、实体盖章。 满足本规定第五章规定且不具有永久保存价值或其他重要价值的电子文件，以及无法转换为纸质文件或缩微胶片的电子文件可以仅以电子形式进行归档。"},{"i":37,"n":"第三十七条","txt":"机关应当根据档案载体的不同要求对档案进行存储和保管。档案存储和保管应当确保实体安全和信息安全。 机关应当制定档案管理应急预案并定期组织演练，以应对突发事件和自然灾害。档案管理应急预案应当纳入机关总体应急预案。"},{"i":38,"n":"第三十八条","txt":"机关应当做好档案防火、防盗、防紫外线、防有害生物、防水、防潮、防尘、防高温、防污染等防护工作。库房温湿度应当符合《档案馆建筑设计规范》（JGJ 25）规定。 档案库房不得存放与档案保管、保护无关的物品。"},{"i":39,"n":"第三十九条","txt":"档案工作人员应当监测和记录库房温湿度，根据需要采取措施调节；定期检查维护档案库房设施设备，确保正常运转；定期清扫除尘，保持库房清洁；定期采取措施，防止鼠虫霉等。"},{"i":40,"n":"第四十条","txt":"机关档案部门应当定期组织人员对档案数量进行清点、对保管状况进行检查，定期对电子档案的保管情况、读取状况等进行检查，发现问题应当及时处理，并建立检查和处理情况台账。"},{"i":41,"n":"第四十一条","txt":"档案工作人员应当及时对受损、易损档案进行修复、复制或作其他技术处理。档案修复应当保持档案内容的完整，尽量维持档案的原貌。档案修复前应当做好登记和检查工作，必要时进行复制备份，做出修复说明。"},{"i":42,"n":"第四十二条","txt":"机关应当为档案工作人员配备劳动保护用品，避免档案管理过程中有毒有害物质损害健康。"},{"i":43,"n":"第四十三条","txt":"机关应当定期对已达到保管期限的档案进行鉴定处置。鉴定工作应当在档案工作协调机制下进行，由办公厅（室）负责人主持，档案部门会同相关业务部门有关人员组成鉴定小组共同开展，必要时可邀请相关领域专家参与。 鉴定结束后，应当形成鉴定工作报告。对仍需继续保存的档案，应当重新划定保管期限并作出标注；对确无保存价值的档案，应当按规定予以销毁。"},{"i":44,"n":"第四十四条","txt":"经鉴定可以销毁的档案，应当按照以下程序销毁： （一）机关档案部门编制档案销毁清册，列明拟销毁档案的档号、文号、责任者、题名、形成时间、应保管期限、已保管时间和销毁时间等内容，按档案工作协调机制报请审核批准； （二）机关分管档案工作的单位负责人、办公厅（室）负责人、档案部门负责人、相关业务部门负责人、档案部门经办人、相关业务部门经办人在档案销毁清册上签署意见； （三）机关档案部门组织档案销毁工作，并与相关业务部门共同派员监销。监销人在档案销毁前，应当按照档案销毁清册所列内容进行清点核对；在档案销毁后，应当在档案销毁清册上签名或盖章。销毁清册应当永久保存。"},{"i":45,"n":"第四十五条","txt":"档案销毁应当在指定场所进行。 电子档案和档案数字复制件需要销毁的，除在指定场所销毁离线存储介质外，还应当确保电子档案和档案数字复制件从系统中彻底删除。销毁时应当留存电子档案和档案数字复制件元数据，并在管理过程元数据、审计日志中自动记录销毁活动。 涉密档案的销毁应当符合《国家秘密载体销毁管理规定》。"},{"i":46,"n":"第四十六条","txt":"机关应当积极开展档案利用工作，建立健全档案利用制度，根据档案的密级、内容和利用方式，规定不同的利用权限、范围和审批手续。机关保管的档案对外提供利用的，需经本单位负责人批准。 利用档案应当履行查阅手续，进行档案查阅登记和利用效果反馈记录。档案工作人员应当对利用活动及时跟踪和监督。"},{"i":47,"n":"第四十七条","txt":"机关应当按照《中华人民共和国政府信息公开条例》等有关规定，及时向同级国家综合档案馆提供主动公开的政府信息文件资料。"},{"i":48,"n":"第四十八条","txt":"机关应当积极推进档案信息开发工作，采取编制全宗介绍、组织沿革、大事记、基础数字汇编、专题文件汇集，以及举办陈列展览、拍摄专题片等多种形式，发挥档案价值。 全宗介绍、组织沿革等应当纳入全宗卷管理。"},{"i":49,"n":"第四十九条","txt":"机关应当积极采用数据分析、文本挖掘等新方法，扩展档案开发的力度和深度。"},{"i":50,"n":"第五十条","txt":"机关应当建立完善统计工作，对所保管档案情况、档案年度出入库情况、档案设施设备情况、档案利用情况、档案移交进馆情况、档案鉴定销毁情况、档案信息化情况、档案工作人员情况、档案业务社会化服务等情况定期统计并建立完备的台账。 统计结果应当真实、准确、完整，支持以可视化方式显示，便于统计分析。"},{"i":51,"n":"第五十一条","txt":"机关应当编制档案工作情况统计年报，汇总分析当年档案工作情况形成年度报告，报送同级档案行政管理部门、上级档案部门。 机关应当加强对档案工作变化情况的分析，为决策提供参考。"},{"i":52,"n":"第五十二条","txt":"机关应当按照国家规定定期向同级国家综合档案馆移交档案。移交档案时，应当同时移交检索工具、编研成果。传统载体档案的数字复制件应当与档案原件一并移交。 机关向国家综合档案馆移交前，应当按照相关规定做好移交档案的密级变更或解除工作，并提出划控与开放意见。"},{"i":53,"n":"第五十三条","txt":"电子档案一般自形成之日起5年内向国家综合档案馆移交，也可按本规定第五十二条与相应的纸质文件或缩微胶片同步移交。 电子档案移交可以采用在线移交或离线移交。在线移交应当通过档案行政管理部门指定的电子档案接收系统和专用网络，不得通过未设置安全可靠措施的互联网移交。 电子档案移交后，机关继续留存的，应当按照档案管理的要求进行管理。"},{"i":54,"n":"第五十四条","txt":"机关撤销或合并的，档案移交按照下列办法进行： （一）撤销机关的档案，应当由有关主管机关代管或按照规定向同级国家综合档案馆移交； （二）撤销机关的业务分别划归几个机关的，其档案不得分散，可由其中一个机关代管或向同级国家综合档案馆移交； （三）一个机关并入另一个机关或几个机关合并为一个新的机关，其档案应当移交给合并后的机关代管或向同级国家综合档案馆移交； （四）机关所属机构撤销的，其档案由主管机关代管，属于国家综合档案馆接收范围的可按照规定向同级国家综合档案馆移交。"},{"i":55,"n":"第五十五条","txt":"机关应当加强档案信息化工作，将机关档案信息化工作纳入机关电子政务和信息化总体规划。 机关档案信息化工作应当与机关信息化建设、档案馆信息化建设协调配合，实现系统互联互通，资源共享共用。"},{"i":56,"n":"第五十六条","txt":"机关应当开展数字档案室建设，统筹传统载体档案数字化、电子文件归档与电子档案管理工作。数字档案室建设按照《数字档案室建设指南》执行。"},{"i":57,"n":"第五十七条","txt":"机关应当建立档案数字化常态机制，有序开展档案数字化工作。 档案数字化应当符合真实性管理要求，数字化过程的元数据应当收集齐全，数字化复制件应当保持原貌并纳入电子档案管理系统统一管理。"},{"i":58,"n":"第五十八条","txt":"纸质档案数字化按照《纸质档案数字化规范》（DA/T 31）执行，录音录像档案数字化按照《录音录像档案数字化规范》（DA/T 62）执行。其他传统载体档案数字化参照有关规定执行。 机关应当积极实施纸质档案数字复制件的全文识别，将现有图像数据转化为文本信息，便于检索和开发利用。"},{"i":59,"n":"第五十九条","txt":"机关应当开展室藏传统载体档案目录数据库建设，数据库质量符合《档案著录规则》（DA/T 18）等标准规范要求。 各门类传统载体档案目录数据应当与相应数字化元数据、电子档案管理系统相应元数据库融合管理。"},{"i":60,"n":"第六十条","txt":"机关应当建立电子文件归档与电子档案管理制度，按照《电子文件归档与电子档案管理规范》（GB/T 18894）确定的职责与分工开展电子文件归档与电子档案管理工作。"},{"i":61,"n":"第六十一条","txt":"机关配备的网络基础设施、系统硬件、基础软件、安全保障系统、终端及辅助设备应当满足档案信息化的管理需要并适当冗余、方便扩展。 机关档案部门应当配置独立的专业服务器和专用存储设备。服务器和存储设备应当满足高效、可用、可扩展等要求。 机关在电子政务云或自建私有云上建设电子档案管理系统的，其计算资源、存储资源和安全防范等应当满足电子文件和电子档案管理要求。不得使用电子政务云之外的其他公有云存储管理电子文件、电子档案。"},{"i":62,"n":"第六十二条","txt":"机关办公自动化系统和其他业务系统应当嵌入电子文件分类方案、归档范围与保管期限表和整理要求，在电子文件形成时自动或半自动开展鉴定、整理工作，实施预归档。 电子档案管理系统应当功能完善、适度前瞻，满足电子档案真实性、可靠性、完整性、可用性管理要求。电子档案管理系统基本功能和可选功能应当参照《数字档案室建设指南》《数字档案室建设评价办法》《电子文件管理系统通用功能要求》（GB/T 29194）以及同级国家综合档案馆的相关要求执行。 电子档案管理系统等级保护不得低于二级标准，分级保护等级应当与电子档案最高密级相适应。使用电子政务云服务的，应当与电子政务云管理机构明确安全管理责任。"},{"i":63,"n":"第六十三条","txt":"电子档案的文件格式和质量应当符合标准要求，元数据应当齐全完整，满足长期保存和同级国家综合档案馆进馆要求。"},{"i":64,"n":"第六十四条","txt":"机关应当为电子档案安全存储配置在线存储系统。在线存储系统应当实施容错技术方案，定期扫描、诊断存储设备。"},{"i":65,"n":"第六十五条","txt":"机关应当制定电子档案备份方案和策略，采用磁带、一次性刻录光盘、硬磁盘等离线存储介质对电子档案实行离线备份。具备条件的，应当对电子档案进行近线备份和容灾备份。 机关应当根据需要制定电子档案转换与迁移方案和策略，转换与迁移活动应当记入电子档案管理过程元数据。"},{"i":66,"n":"第六十六条","txt":"机关应当统筹开展传统载体档案数字化、电子文件归档与电子档案管理的安全保密工作，采取有效措施严防信息篡改、丢失、外泄。涉密档案进行数字化、涉密电子文件归档与电子档案管理应当严格遵守保密规定。"},{"i":67,"n":"第六十七条","txt":"有下列情形之一的，由县级以上档案行政管理部门单独或联合有关部门，或由本单位给予表彰奖励： （一）档案收集、整理、移交做出显著成绩的； （二）档案的保管、保护和现代化管理做出显著成绩的； （三）档案利用、开发取得突出效果的； （四）档案学理论研究、档案科研做出重要贡献的； （五）同违反档案法律、法规的行为作斗争，表现突出的； （六）从事专（兼）职档案工作满15年的。"},{"i":68,"n":"第六十八条","txt":"有下列行为之一的，由县级以上档案行政管理部门责令限期改正；情节严重的，由有关主管部门对机关直接负责的主管人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。 （一）机关未统一管理机关档案或未按规定形成、收集档案的； （二）机关未按规定设置档案工作机构或未指定档案工作负责部门，未按要求配备专（兼）职档案工作人员的； （三）将机关应当归档的文件材料据为己有，拒绝移交机关档案部门的； （四）档案管理不符合档案安全保护要求的； （五）拒不按照国家规定向国家综合档案馆移交档案的； （六）明知所保存的档案面临危险而不采取措施，造成档案损失的；档案工作人员、对档案工作负有领导责任的人员玩忽职守，造成档案损失的。"},{"i":69,"n":"第六十九条","txt":"本规定由国家档案局负责解释。事业单位、《社会团体登记管理条例》界定的社会团体可参照执行。"},{"i":70,"n":"第七十条","txt":"本规定自2019年1月1日起施行。"}],"cunjidanganguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强农村档案工作, 规范村级档案管理，服务新形势下的农村工作，根据《中华人民共和国档案法》《中华人民共和国村民委员会组织法》《中华人民共和国农业法》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称村级档案是指村党组织、村民委员会、村集体经济组织等（以下简称村级组织）在党组织建设、村民自治、生产经营等活动中形成的具有保存价值的文字、图表、音像等不同形式和载体的历史记录。"},{"i":3,"n":"第三条","txt":"村级档案工作主要包括村级组织对村级档案进行的收集、整理、保管、鉴定、利用等工作。"},{"i":4,"n":"第四条","txt":"村级档案工作实行统一领导、集中管理、安全方便的原则。 村级组织应将档案工作作为村级工作的重要事项，健全相应的工作制度，明确领导、健全机制、保障经费，确保档案的真实、完整、规范和安全。"},{"i":5,"n":"第五条","txt":"村级档案工作在业务上接受乡镇人民政府、档案行政管理部门、民政部门、农业部门和相关部门的监督和指导。"},{"i":6,"n":"第六条","txt":"村级组织应当指定专人负责档案的收集、管理和提供利用。有条件的村应当设立专用档案柜和档案库房集中管理档案。 档案管理人员应当具有良好的政治素质，遵纪守法，忠于职守，具备相应的档案管理知识，并经过一定的档案业务培训。"},{"i":7,"n":"第七条","txt":"村级组织形成的具有保存价值的文件材料，均应当按照要求规范整理后归档，任何组织和个人不得据为己有或者拒绝归档。 县级档案行政管理部门可以依据《村级文件材料归档范围和档案保管期限表》（见附件）的规定，制定符合本地实际的村级文件材料归档范围和档案保管期限表。"},{"i":8,"n":"第八条","txt":"村级档案一般包括文书、基建项目、设施设备、会计、音像、实物等类别。各类文件材料整理方法和归档时间如下： （一）文书类应当按照《文书档案案卷格式》（GB/T 9705-2008）或者《归档文件整理规则》（DA/T 22-2015）的要求进行整理，于次年上半年归档。 （二）基建项目类应当按照《科学技术档案案卷构成的一般要求》（GB/T 11822-2008），并参照《国家重大建设项目文件材料归档要求与档案整理规范》（DA/T 28-2002）的有关规定及时整理归档。 （三）设施设备类应当在开箱验收后即时归档，使用维修记录等按照《科学技术档案案卷构成的一般要求》进行收集管理。 （四）会计类应当按照《会计档案管理办法》（财政部 国家档案局令第79号）的要求进行收集整理，在会计年度终了后于次年3月底之前归档。 （五）照片应当按照《照片档案管理规范》（GB/T 11821-2002）、《数码照片归"},{"i":9,"n":"第九条","txt":"档案制成材料和装订材料应当符合档案保护的要求。"},{"i":10,"n":"第十条","txt":"档案库房应当采取防火、防盗、防水（潮）、防光、防尘、防磁、防高温、防有害生物等措施。 档案管理人员应当定期检查档案的保管状况，确保档案安全。对音像档案和电子档案，要定期检查信息记录的安全性，确保档案可读可用。"},{"i":11,"n":"第十一条","txt":"不具备档案安全保管条件的，应当将档案交由乡镇档案机构代为保管，村级组织可以保存档案目录等检索工具以方便利用。"},{"i":12,"n":"第十二条","txt":"村级组织换届选举后10日内，应当履行档案交接手续。必要时可以在选举前将档案暂存乡镇政府。村以及村民小组在设立、撤销、范围调整时，应当将档案妥善移交。 档案工作人员离任时应当进行档案移交，履行交接手续，防止档案散失。"},{"i":13,"n":"第十三条","txt":"销毁已达到保管期限的档案时，应当成立档案鉴定工作小组及时进行鉴定。 鉴定工作小组由村级档案管理人员和形成档案的村级组织的人员（或者村民代表）组成，鉴定后应当形成档案鉴定报告。对失去保存价值的档案，应当清点核对并编制档案销毁清册，经过必要的审批手续后按照规定销毁。 禁止擅自销毁档案。村级档案销毁清册应当永久保存。"},{"i":14,"n":"第十四条","txt":"村级档案工作应当积极推进档案信息化建设，配备必要的设施设备和档案管理软件，建立档案电子目录和全文数据库，逐步实现档案的信息网络共享。"},{"i":15,"n":"第十五条","txt":"村级档案工作应当建立档案查阅利用制度，为本村各类组织及其成员、村民提供服务。查阅档案要遵守利用规定、履行查阅手续，不得有涂改、损毁、调换、抽取档案等行为。 档案管理人员应当围绕村中心工作或村级组织及其成员、村民利用需求，加强档案信息资源的开发利用，积极开展档案编研工作，如编写村史、村志、大事记等。"},{"i":16,"n":"第十六条","txt":"对在村级档案工作中作出突出贡献的村干部、档案工作人员和其他组织、个人，由各级人民政府、档案行政管理部门及相关单位给予表彰和奖励。"},{"i":17,"n":"第十七条","txt":"各省（自治区、直辖市）、新疆生产建设兵团档案行政管理部门商同级民政部门和农业部门，可以结合本办法和本地实际，制定实施办法及细则。"},{"i":18,"n":"第十八条","txt":"本办法由国家档案局、民政部、农业部负责解释。"},{"i":19,"n":"第十九条","txt":"本办法自2018年1月1日起施行。 附件：村级文件材料归档范围和档案保管期限表 村级文件材料归档范围和档案保管期限表 一、文书类 1.党群组织工作文件材料 1.1本村党组织(党委、党总支、党支部)委员会会议记录、党员大会会议记录、村“两委”联席（班子）会议记录，永久 1.2本村党组织年度工作计划、总结等材料，永久 1.3本村党组织关于机构设置、撤并、名称更改、启用和废止印章的请示，上级批复、通知、决定等材料，永久 1.4本村党务干部任免、分工、考察、奖惩等材料，永久 1.5本村党组织换届选举候选人的请示、批复和换届选举工作的通知、议程、报告、领导人讲话、大会发言、选举办法、选举结果、决议、上级批复等材料，永久 1.6本村党员教育培训、组织活动、党性分析、民主评议等方面的计划、总结、会议（活动）记录、请示及上级的批复，永久 1.7本村发展新党员，党员转正、延期、退党，处置不合格党员等方面"}],"danganzhifajiandujianchagongzuozanxingguiding":[{"i":1,"n":"第一条","txt":"为实施档案法规，加强档案行政管理部门的行政监督职能，依据《中华人民共和国档案法》和《档案法实施办法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称档案执法监督检查，是指各级档案行政管理部门对贯彻实施档案法规的监督检查以及依法对违反档案法规行为的查处。"},{"i":3,"n":"第三条","txt":"国家档案局和县级以上档案行政管理部门是国家贯彻并监督执行档案法规的机关，依法行使档案执法监督检查权，并依法对违反档案法规的行为进行查处。"},{"i":4,"n":"第四条","txt":"国家档案局和省、自治区、直辖市档案局应设档案执法监督检查机构，计划单列市、省（自治区）辖市、行署和县级档案行政管理部门应设档案执法监督检查机构和监督检查员，负责组织、协调各自管辖范围内的档案执法监督检查工作。"},{"i":5,"n":"第五条","txt":"档案执法监督检查机构的职责是： （一）宣传贯彻《档案法》、《档案法实施办法》和其它档案法规、规章； （二）监督检查档案法规的实施情况；（三）调查处理管辖范围内的违反《档案法》案件；对轻微违法行为进行批评教育或发出《档案执法监督检查通知书》（见格式一）；对构成犯罪的，移交司法机关追究刑事责任； （四）承担上级档案行政管理部门统一组织的案件查处和其他档案执法监督检查任务； （五）组织总结、交流本行政区域档案执法监督检查工作的经验； （六）对同违反档案法律、法规的行为作斗争表现突出的人员或者集体，提出表扬和奖励的建设。"},{"i":6,"n":"第六条","txt":"档案执法监督检查人员，必须遵守国家法律、法规和政策，廉洁正派，秉公执法，并要具备下列条件之一： （一）高等院校法律专业毕业，在本单位工作一年以上的； （二）具有馆员以上专业职称，熟悉档案法律、法规的； （三）熟悉档案工作业务，经过法律知识培训，确已掌握与档案有关法律知识的。"},{"i":7,"n":"第七条","txt":"专职或兼职档案执法监督检查员均发给《执法监督检查证》。中央国家机关监督检查员证由国家档案局负责制作与填发；地方监督检查员证分别由各省、自治区、直辖市档案局及计划单列市档案局负责制作并填发。"},{"i":8,"n":"第八条","txt":"县级以上档案行政管理部门对各自管辖范围内档案法规的贯彻实施情况进行监督检查。档案执法监督检查应与档案业务工作密切结合，检查的内容和重点应根据档案法规实施的情况具体确定。"},{"i":9,"n":"第九条","txt":"档案执法监督检查的主要形式为： 一、对规章、规范性文件备案审查； 二、建立档案行政执法情况报告制度； 三、开展各种形式的档案执法检查； 四、受理群众举报、申诉； 五、法律、法规规定的其它形式。"},{"i":10,"n":"第十条","txt":"对下列行为，档案执法监督检查机构和执法监督检查员可以发出《档案执法监督检查通知书》： （一）未建立档案工作或档案管理制度的； （二）档案保管条件差，危及档案安全的； （三）档案管理制度不健全或执行制度不严，可能造成档案损毁的； （四）发现档案破损、变质、下落不明或泄密等情况，未及时采取有效措施的； （五）拒不向本单位档案部门移交应当立卷归档的文件材料的； （六）不按规定向档案馆移交档案的； （七）科研成果、产品试制、基建工程或其他技术项目鉴定验收时，未按规定验收档案，致使档案残缺不全的； （八）借阅档案未按规定及时归还，且屡催不还的； （九）在保管或利用档案中涂改、撕毁、丢失档案的； （十）其它可能导致档案损毁的行为。 《档案执法监督检查通知书》应写明被监督检查单位或个人所违反的具体档案法规条款和违法事实以及改进要求。"},{"i":11,"n":"第十一条","txt":"本规定所称对违法案件的查处，是指县级以上各级档案行政管理部门对违反档案法规但尚未构成犯罪行为的查处。 县级以上各级档案行政管理部门对具有《档案法》第二十四条、《档案法实施办法》第二十八条所列违法行为，应依法查处。"},{"i":12,"n":"第十二条","txt":"违反《档案法》案件，按下列分工查处： （一）各机关、社会团体、企事业单位和其他组织的违反《档案法》案件，由同级或上级档案行政管理部门查处，必要时会同其上级主管机关查处； （二）各级档案馆违反《档案法》案件，由同级档案行政管理部门或上一级档案行政管理部门查处； （三）各级档案行政管理部门违反《档案法》案件，由上一级档案行政管理部门或上级主管机关查处。"},{"i":13,"n":"第十三条","txt":"凡符合本规定第十一条规定查处的违反《档案法》案件，查处机关都应受理；如按本规定第十二条规定不应由本单位受理的，要及时移送有权受理的机关。"},{"i":14,"n":"第十四条","txt":"上级档案行政管理部门有权纠正下级档案行政管理部门查处违反《档案法》案件的错误或不适当的决定。"},{"i":15,"n":"第十五条","txt":"查处违反《档案法》案件，必须以事实为依据，以法律为准绳，做到事实清楚，证据确凿，定性准确，处理恰当，手续完备。"},{"i":16,"n":"第十六条","txt":"查处违反《档案法》案件的程序为： ______调查 ______处理 ______上报备案"},{"i":17,"n":"第十七条","txt":"县级以上档案行政管理部门应认真审查违反《档案法》案件，并负责组织调查。必要时与有关部门组成联合调查组，共同进行调查。 调查人员每次不得少于2人，与本案有利害关系或者有其它关系可能影响查处工作的，应当回避。"},{"i":18,"n":"第十八条","txt":"调查违反《档案法》案件时，档案执法监督检查员应出示《执法监督检查员》证。其它调查人员应持有关部门的证明文件。"},{"i":19,"n":"第十九条","txt":"依照本规定，对违反《档案法》案件调查清楚后，确认违法事实清楚，证据确凿，情节较重但尚未构成犯罪的，由查处机关依法提出处理意见，签发《违法行为处理通知书》（见格式二），直接通知违法单位法定代表人或违法行为人所在单位协助执行。 确认违反档案法规行为构成犯罪的，由查处机关按法定程序移交发生违法行为地的司法机关追究其刑事责任。"},{"i":20,"n":"第二十条","txt":"有关部门接到《违法行为处理通知书》后，应按通知书提出的意见处理并将处理结果回执退回；如对处理意见有异议，应于接到该通知书之日起15日内向通知书发出机关提出书面意见。15日内既不退回处理结果回执，又不向通知书发出机关提出书面意见，查处机关有权询问情况和建议其上级机关督促执行。"},{"i":21,"n":"第二十一条","txt":"当事人对处理决定不服，可以向作出决定机关的上一级机关提出申诉；属于监察机关监察对象的人员，也可以向同级或上级监察机关提出申诉。受理申诉的机关应在30日内作出决定，并将结果通知申诉人。 申诉期间不停止对处理决定的执行。"},{"i":22,"n":"第二十二条","txt":"查处机关应将结案的违反《档案法》案件的有关材料按规定格式（见格式三）填报，向上一级档案行政管理部门备案。"},{"i":23,"n":"第二十三条","txt":"本规定由国家档案局负责解释。"},{"i":24,"n":"第二十四条","txt":"各省、自治区、直辖市档案局和计划单列市档案局可以根据本规定，结合本地区实际情况制定实施细则，并报国家档案局备案。"},{"i":25,"n":"第二十五条","txt":"本规定自发布之日起施行。"}],"danganxingzhengchufachengxuguiding":[{"i":1,"n":"第一条","txt":"为了规范档案行政处罚程序，保障和监督档案主管部门依法实施行政处罚，保护公民、法人或者其他组织的合法权益，根据《中华人民共和国行政处罚法》等法律法规，结合档案工作实际，制定本规定。"},{"i":2,"n":"第二条","txt":"档案主管部门实施行政处罚，适用本规定。"},{"i":3,"n":"第三条","txt":"实施档案行政处罚应当遵循公正、公开的原则，坚持处罚与教育相结合，做到事实清楚、证据充分、适用依据正确、程序合法、处罚适当。"},{"i":4,"n":"第四条","txt":"档案主管部门应当全面落实行政执法公示制度、执法全过程记录制度、重大执法决定法制审核制度。加强行政执法信息化建设，提高行政执法效率。"},{"i":5,"n":"第五条","txt":"档案主管部门实施行政处罚实行回避制度。参与案件办理的有关人员与案件有直接利害关系或者有其他关系可能影响公正执法的，应当回避。回避决定作出之前，不停止案件调查。"},{"i":6,"n":"第六条","txt":"档案主管部门及其工作人员对实施行政处罚过程中知悉的国家秘密、商业秘密、工作秘密或者个人隐私，应当依法予以保密。"},{"i":7,"n":"第七条","txt":"上级档案主管部门对下级档案主管部门作出的行政处罚，应当加强监督。"},{"i":8,"n":"第八条","txt":"档案行政处罚由违法行为发生地的县级以上档案主管部门管辖。法律、行政法规、部门规章另有规定的，从其规定。"},{"i":9,"n":"第九条","txt":"国家档案主管部门管辖下列案件： （一）违法行为涉及中央和国家机关各部门、中央企业、中央和国务院直属事业单位以及全国性人民团体的； （二）全国范围内特别重大、复杂的案件。"},{"i":10,"n":"第十条","txt":"省、自治区、直辖市档案主管部门应当按照职权法定、属地管理的原则，结合违法行为涉及区域、案情复杂程度、社会影响范围等因素，厘清本行政区域内不同层级档案主管部门行政处罚管辖范围，明确职责分工。"},{"i":11,"n":"第十一条","txt":"两个以上档案主管部门都有管辖权的，由最先立案的档案主管部门管辖。 对管辖发生争议的，应当自发生争议之日起七个工作日内协商解决，协商不成的，报请共同的上一级档案主管部门指定管辖；也可以直接由共同的上一级档案主管部门指定管辖。"},{"i":12,"n":"第十二条","txt":"档案主管部门发现案件不属于本部门管辖的，应当依法移送有关部门。 违法行为涉嫌犯罪的，档案主管部门应当及时将案件移送司法机关，追究刑事责任。"},{"i":13,"n":"第十三条","txt":"档案主管部门实施行政处罚时，应当责令当事人改正或者限期改正违法行为。 当事人有违法所得，除依法应当予以退赔的外，应当予以没收。违法所得是指实施违法行为所取得的款项。法律、行政法规、部门规章对违法所得的计算另有规定的，从其规定。"},{"i":14,"n":"第十四条","txt":"档案违法行为在二年内未被发现的，不再给予行政处罚，法律另有规定的除外。 前款规定的期限，从违法行为发生之日起计算；违法行为有连续或者继续状态的，从行为终了之日起计算。"},{"i":15,"n":"第十五条","txt":"实施档案行政处罚，适用违法行为发生时的法律、法规、规章的规定。但是作出行政处罚决定时，法律、法规、规章已被修改或者废止，且新的规定处罚较轻或者不认为是违法的，适用新的规定。"},{"i":16,"n":"第十六条","txt":"档案主管部门对依据监督检查职权或者通过投诉、举报、其他部门移送、上级交办等途径发现的违法行为线索，应当自发现线索或者收到相关材料之日起十五个工作日内予以核查并决定是否立案；特殊情况下，经档案主管部门负责人批准，可以延长十五个工作日。法律、法规、规章另有规定的除外。 检测、检验、鉴定及权利人辨认或者鉴别等所需时间，不计入前款规定期限。"},{"i":17,"n":"第十七条","txt":"经核查，符合下列条件的，应当立案： （一）有初步证据证明存在违反档案管理法律、法规、规章的行为； （二）依据档案管理法律、法规、规章应当给予行政处罚； （三）属于本部门管辖； （四）违法行为未超过行政处罚时效。 决定立案的，应当填写立案审批表，由两名以上具有行政执法资格的执法人员负责调查处理。"},{"i":18,"n":"第十八条","txt":"档案主管部门对档案违法案件应当全面、客观、公正地进行调查，依法收集、调取有关证据；必要时，按照法律、行政法规的规定进行检查。"},{"i":19,"n":"第十九条","txt":"执法人员在进行调查或者检查时，不得少于两人，并应当主动向当事人或者有关人员出示执法证件。 执法人员应当文明执法，尊重和保护当事人合法权益。 当事人或者有关人员应当协助调查或者检查，不得拒绝或者阻挠。"},{"i":20,"n":"第二十条","txt":"证据包括:书证、物证、视听资料、电子数据、证人证言、当事人的陈述、鉴定意见、勘验笔录和现场笔录。 立案前核查或者监督检查过程中依法取得的证据材料，可以作为案件的证据使用。对于移送的案件，移送机关依职权调查收集的证据材料，可以作为案件的证据使用。 证据经查证属实，方可作为认定案件事实的根据。以非法手段取得的证据，不得作为认定案件事实的根据。"},{"i":21,"n":"第二十一条","txt":"收集、调取的书证、物证应当是原件、原物。调取原件、原物有困难的，可以提取复制件、影印件或者抄录件，也可以拍摄或者制作足以反映原件、原物外形或者内容的照片、录像。复制件、影印件、抄录件和照片、录像由证据提供人核对无误后注明与原件、原物一致，并注明出证日期、证据出处，同时签名或者盖章。"},{"i":22,"n":"第二十二条","txt":"收集、调取的视听资料、电子数据应当是有关资料的原始载体。收集、调取原始载体有困难的，可以采用复制等方式取证，并注明制作方法、制作时间、制作人等。声音资料应当附有该声音内容的文字记录。"},{"i":23,"n":"第二十三条","txt":"对与案件有关的物品或者场所进行检查时，应当通知当事人到场。执法人员应当制作现场笔录，载明时间、地点、事件等内容，由执法人员、当事人签名或者盖章。 当事人拒不到场、无法找到当事人或者当事人拒绝签名或盖章的，执法人员应当在笔录中注明，必要时可以邀请有关人员作为见证人。"},{"i":24,"n":"第二十四条","txt":"执法人员可以询问当事人或有关人员。询问应当个别进行，并制作询问笔录。询问笔录应当交被询问人核对；对阅读有困难的，应当向其宣读。笔录如有差错、遗漏，应当允许其更正或者补充。涂改部分应当由被询问人签名、盖章或者以其他方式确认。经核对无误后，由被询问人在笔录上逐页签名、盖章或者以其他方式确认。执法人员应当在笔录上签名。 被询问人拒绝签名、盖章或者按指纹的，由执法人员在笔录上注明情况。"},{"i":25,"n":"第二十五条","txt":"为查明案情，需要对案件中专门事项进行检测、检验、鉴定、评估、认定的，应当委托具备相应条件的机构进行。检测、检验、鉴定、评估、认定意见应当告知当事人。"},{"i":26,"n":"第二十六条","txt":"档案主管部门因实施行政处罚的需要，可以向有关机关出具协助函，请求有关机关协助进行调查取证等。"},{"i":27,"n":"第二十七条","txt":"案件调查终结，执法人员应当制作案件调查报告。 案件调查报告的内容包括：当事人的基本情况、案件来源、调查过程、案件事实、证据材料、法律依据、处理建议等。"},{"i":28,"n":"第二十八条","txt":"在作出《中华人民共和国行政处罚法》第五十八条规定情形的行政处罚决定前，办案机构应当将案件调查报告连同案件材料，交由档案主管部门法制机构进行审核。 档案行政处罚法制审核工作由档案主管部门法制机构负责；未设置法制机构的，由档案主管部门确定的承担法制审核工作的其他机构或者人员负责。 案件查办人员不得同时作为该案件的法制审核人员。档案主管部门中初次从事行政处罚决定法制审核的人员，应当通过国家统一法律职业资格考试取得法律职业资格。"},{"i":29,"n":"第二十九条","txt":"档案行政处罚决定法制审核的主要内容包括： （一）是否超越本机关法定权限； （二）当事人基本情况、案件事实是否清楚，证据是否确实、充分； （三）程序是否合法； （四）适用法律依据是否正确； （五）行政执法文书是否规范； （六）违法行为是否涉嫌犯罪、需要移送司法机关； （七）其他需要审核的内容。"},{"i":30,"n":"第三十条","txt":"负责法制审核工作的机构或人员应当自收到审核材料之日起七个工作日内完成审核，并提出以下书面意见： （一）对事实清楚、证据合法充分、适用依据准确、处罚适当、程序合法的案件，同意处罚意见； （二）对事实不清、证据不足的案件，建议补充调查； （三）对适用依据不准确、处罚不当、程序不合法的案件，建议改正； （四）对超出法定权限的案件，建议按有关规定移送； （五）认为有必要提出的其他意见和建议。"},{"i":31,"n":"第三十一条","txt":"拟作出档案行政处罚的案件，在作出行政处罚决定前，应当书面告知当事人拟作出的行政处罚内容及事实、理由、依据，并告知当事人依法享有陈述权、申辩权。 当事人自告知书送达之日起五个工作日内，未行使陈述、申辩权，视为放弃此权利。"},{"i":32,"n":"第三十二条","txt":"档案主管部门拟作出《中华人民共和国行政处罚法》第六十三条所列行政处罚决定的，应当告知当事人有要求举行听证的权利；当事人要求听证的，应当在被告知后五个工作日内提出，档案主管部门应当组织听证。当事人不承担听证的费用。"},{"i":33,"n":"第三十三条","txt":"档案主管部门在告知当事人拟作出的行政处罚决定后，应当充分听取当事人的意见，对当事人提出的事实、理由和证据进行复核。当事人提出的事实、理由或者证据成立的，档案主管部门应当予以采纳，不得因当事人陈述、申辩或者要求听证而给予更重的行政处罚。"},{"i":34,"n":"第三十四条","txt":"档案主管部门负责人对调查终结的档案违法案件根据不同情况可以分别作出如下决定： （一）确有依法应当给予行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）确有违法行为，但有依法不予行政处罚情形的，不予行政处罚； （三）违法事实不能成立的，不予行政处罚； （四）违法行为涉嫌犯罪的，移送司法机关； 对于案情复杂或者重大违法行为给予较重的行政处罚的，档案主管部门负责人应当集体讨论决定。"},{"i":35,"n":"第三十五条","txt":"档案主管部门给予行政处罚的，应当制作行政处罚决定书。行政处罚决定书应当载明下列事项： （一）当事人的姓名或者名称、地址等基本情况； （二）违反法律、法规或者规章的事实和证据； （三）当事人陈述、申辩的采纳情况及理由； （四）行政处罚的种类和依据； （五）行政处罚的履行方式和期限； （六）申请行政复议、提起行政诉讼的途径和期限； （七）作出行政处罚决定的档案主管部门名称和作出决定的日期。 行政处罚决定书必须盖有作出行政处罚决定的档案主管部门的印章。"},{"i":36,"n":"第三十六条","txt":"档案主管部门应当自立案之日起九十日内作出行政处罚决定。因案情复杂或者其他原因，不能在规定期限内作出处理决定的，经档案主管部门负责人批准，可以延长三十日。案情特别复杂或者有其他特殊情况，经延期仍不能作出处理决定的，应当由档案主管部门负责人集体讨论决定是否继续延期，决定继续延期的，应当同时确定延长的合理期限。 案件处理过程中，听证、检测、检验、鉴定、权利人辨认或者鉴别等时间不计入前款所指的案件办理期限。"},{"i":37,"n":"第三十七条","txt":"行政处罚决定书应当在宣告后当场交付当事人；当事人不在场的，档案主管部门应当在七个工作日内依照《中华人民共和国民事诉讼法》的有关规定，将行政处罚决定书送达当事人。 当事人同意并签订确认书的，档案主管部门可以采用传真、电子邮件等方式，将行政处罚决定书等送达当事人。"},{"i":38,"n":"第三十八条","txt":"行政处罚决定依法作出后，当事人应当在行政处罚决定书载明的期限内，予以履行。 当事人应当自收到行政处罚决定书之日起十五日内，到指定的银行或者通过电子支付系统缴纳罚款。 当事人确有经济困难，需要延期或者分期缴纳罚款的，经当事人申请和档案主管部门批准，可以暂缓或者分期缴纳。"},{"i":39,"n":"第三十九条","txt":"案件有以下情形之一的，办案机构应当在十个工作日内填写结案审批表，经档案主管部门负责人批准后，予以结案： （一）行政处罚决定执行完毕的； （二）依法终结执行的； （三）案件终止调查的； （四）依法作出不予行政处罚决定的； （五）其他应予结案的情形。"},{"i":40,"n":"第四十条","txt":"结案后，办案人员应当将案件材料按照档案管理的有关规定整理归档。案卷归档应当一案一卷、材料齐全、规范有序。"},{"i":41,"n":"第四十一条","txt":"本规定由国家档案局负责解释。"},{"i":42,"n":"第四十二条","txt":"本规定自2023年4月1日起施行。2000年5月10日国家档案局公布的《档案行政处罚程序暂行规定》同时废止。"}],"danganxingzhengxukechengxuguiding":[{"i":1,"n":"第一条","txt":"为了规范档案行政许可行为，保障和监督档案行政管理部门有效实施行政管理，保护公民、法人或者其他组织的合法权益，根据《中华人民共和国行政许可法》、《中华人民共和国档案法》和《中华人民共和国档案法实施办法》，制定本规定。"},{"i":2,"n":"第二条","txt":"县级以上人民政府的档案行政管理部门(以下简称档案行政管理部门)实施档案行政许可适用本规定。"},{"i":3,"n":"第三条","txt":"档案行政管理部门依照法定的权限、范围、条件和程序实施行政许可。"},{"i":4,"n":"第四条","txt":"档案行政管理部门实施行政许可，遵循公开、公平、公正、便民和高效的原则。"},{"i":5,"n":"第五条","txt":"档案行政许可实行统一受理制度，档案行政管理部门的法制工作机构（以下简称受理部门）办理行政许可受理事项。"},{"i":6,"n":"第六条","txt":"档案行政管理部门应当在办公场所或网站公示办理行政许可需要提交的申请书示范文本和全部申请材料目录。 申请人要求对公示内容予以说明、解释的，受理部门应当说明、解释，提供准确、可靠的信息。"},{"i":7,"n":"第七条","txt":"申请书主要应当载明以下事项： （一）申请单位名称或个人姓名、地址、联系方式； （二）档案名称、内容、规格、数量； （三）档案移转方式（出卖、转让、赠送、交换、携带出境）和事由； （四）申请单位或个人意见(盖章)； （五）档案或档案的复制件有受让单位的，应注明受让单位名称或个人姓名、地址、联系方式； （六）受理部门认为必须载明的其他事项。"},{"i":8,"n":"第八条","txt":"申请人提交申请材料，应当出示单位介绍信、身份证等身份证明文件，受理部门应当予以核对。 申请人委托他人提交申请材料的，受托人应当提交授权委托书，出示受托人的身份证明文件。 申请人通过信函等方式提交申请材料的，应当附上详细、准确的联系方式并确定送达方式。"},{"i":9,"n":"第九条","txt":"受理部门接到申请材料后，应当根据下列情形分别作出处理： （一）申请材料符合标准的，必须即时受理，并填写档案行政许可申请材料接收凭证和档案行政许可受理通知书； （二）申请事项依法不需要取得行政许可或者申请事项依法不属于档案行政管理部门职权范围的，应当即时告知申请人不予受理，并出具档案行政许可不予受理通知书； （三）申请材料存在可以当场更正的错误的，应当允许申请人当场更正； （四）申请材料不齐全或者不符合法定形式的，应当填写档案行政许可补正材料通知书，将需要补齐补正材料的全部内容、要求当场告知申请人。 以信函等方式提交申请材料的，受理部门应当自接到申请材料之日起五日内作出相应处理。"},{"i":10,"n":"第十条","txt":"档案行政管理部门可以指定受理部门或其他部门办理行政许可审查事项。 受理部门与审查部门不是同一部门的，受理部门决定受理后应当及时办理登记手续，并立即将申请材料移交审查部门。"},{"i":11,"n":"第十一条","txt":"审查部门接到申请材料后，应当按照内部工作流程对申请人提交的申请材料及时进行审查。 审查部门在审查申请材料过程中，必要时应当征询相关部门意见。"},{"i":12,"n":"第十二条","txt":"审查部门对行政许可申请进行审查后提出处理意见，报档案行政管理部门负责人同意后，依法作出行政许可决定： （一）对符合法定条件和标准的行政许可申请，制作准予档案行政许可决定书，发送申请人； （二）对不符合法定条件和标准，或者申请人隐瞒有关情况、提供虚假材料申请行政许可的，制作不予档案行政许可决定书，发送申请人，说明理由并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":13,"n":"第十三条","txt":"档案行政管理部门根据利害关系人的请求或者依据职权，可以依法撤销行政许可，制作撤销档案行政许可决定书，发送被许可人。"},{"i":14,"n":"第十四条","txt":"档案行政管理部门应当自受理行政许可申请之日起二十日内作出行政许可决定。 情况复杂，不能在规定期限内作出决定的，经档案行政管理部门负责人批准，可以延长十日，并制作档案行政许可延期通知书，发送申请人，说明延期理由。"},{"i":15,"n":"第十五条","txt":"档案行政管理部门作出准予或者不予行政许可决定，应当自作出决定之日起十日内向申请人送达准予行政许可或者不予行政许可的书面决定。"},{"i":16,"n":"第十六条","txt":"行政许可文件可以通过邮寄、公告等方式送达申请人。 申请人在接到领取通知五日内不领取行政许可文件且受理部门无法通过邮寄等方式送达的，可以公告送达。自公告之日起，经过六十日，即视为送达。"},{"i":17,"n":"第十七条","txt":"档案行政管理部门在办公场所或网站公示申请材料目录，应当按照《档案行政许可申请材料目录》（见附件1）执行。 档案行政管理部门制作档案行政许可文书，应当按照《档案行政许可文书示范文本》（见附件2）执行，统一编号并加盖档案行政管理部门行政许可专用章。"},{"i":18,"n":"第十八条","txt":"对于非行政许可类的审批项目，档案行政管理部门可以参照本规定执行。"},{"i":19,"n":"第十九条","txt":"本规定所称的档案行政管理部门受理行政许可和作出决定的期限以工作日计算，不含法定节假日。"},{"i":20,"n":"第二十条","txt":"本规定自2005年7月1日起施行。"}],"danganguangongzuotongze":[{"i":1,"n":"第一条","txt":"根据中共中央、国务院有关档案工作的决定和指示，为加强我国档案馆事业的建设，特制定本通则。"},{"i":2,"n":"第二条","txt":"档案馆是党和国家的科学文化事业机构，是永久保管档案的基地，是科学研究和各方面工作利用档案史料的中心。其业务工作受同级和上级档案业务管理机关的指导、监督与检查。"},{"i":3,"n":"第三条","txt":"档案馆的基本任务是在维护党和国家历史真实面貌的前提下，集中统一地管理党和国家的档案及有关资料，维护档案的完整与安全，积极提供利用，为社会主义现代化建设服务。 档案馆进行下列工作： 1.接收与征集档案； 2.科学地管理档案； 3.开展档案的利用工作； 4.编辑出版档案史料； 5.参与编修史、志的工作。"},{"i":4,"n":"第四条","txt":"档案馆必须建立严密的规章制度，维护党和国家的机密，提高工作效率和质量。"},{"i":5,"n":"第五条","txt":"档案馆工作人员要努力学习马克思列宁主义、毛泽东思想，坚持四项基本原则，认真执行党和国家的方针政策，热爱档案事业，刻苦学习档案业务和科学文化知识，不断提高政治思想水平和业务能力，以保证工作任务的顺利完成。"},{"i":6,"n":"第六条","txt":"档案馆接收档案的范围： 1.本级各机关、团体及其所属单位具有永久保存价值的档案，省辖市（州、盟）和县级档案馆同时接收长期保存的档案； 2.属于本馆应接收的撤销机关、团体的档案； 3.属于本馆应接收的中华人民共和国成立以前的各种档案。"},{"i":7,"n":"第七条","txt":"档案馆接收档案的期限： 1.省级以上档案馆接收立档单位保管20年左右的档案； 2.省辖市（州、盟）和县级档案馆接收立档单位保管10年左右的档案。"},{"i":8,"n":"第八条","txt":"档案馆接收档案的要求和手续： 1.进馆档案应保持全宗的完整性，并按规定整理好； 2.立档单位编制的组织沿革、全宗介绍和有关检索工具应随同档案一起接收； 3.交接双方必须根据移交目录清点核对，并在交接文据上签名盖章。"},{"i":9,"n":"第九条","txt":"档案馆要注意接收和收集与本馆馆藏档案有关的各种资料。"},{"i":10,"n":"第十条","txt":"档案馆要加强对历史档案、资料的征集。省级以上档案馆应设立专门机构或配备专职人员进行征集工作。"},{"i":11,"n":"第十一条","txt":"档案馆的档案，要以全宗为单位，进行科学的分类、排列、编号。每个全宗都要建立全宗卷，记载立档单位和全宗历史演变情况。"},{"i":12,"n":"第十二条","txt":"档案库房必须坚固适用，并应具有抗震、防盗、防火、防水、防潮、防尘、防虫、防鼠、防高温、防强光等设施。"},{"i":13,"n":"第十三条","txt":"档案馆应研究和改进档案保护技术，延长档案的寿命。对已破损和字迹褪色的重要档案，要及时修复或复制。"},{"i":14,"n":"第十四条","txt":"档案馆对无需继续保存的档案，必须经过鉴定，并征求有关部门意见，报请主管领导机关批准，方能销毁。未经鉴定和批准，不得销毁任何档案。"},{"i":15,"n":"第十五条","txt":"档案馆应进行下列统计工作： 1.对档案的收进和移出、全宗和案卷数量、利用等情况，及时准确地进行统计； 2.按照统一规定和要求，向同级和上一级档案业务管理机关报送本馆基本情况统计表和全宗卡片，并于每年1月份补报上一年度的全宗变化情况。"},{"i":16,"n":"第十六条","txt":"档案馆应对馆藏档案和资料的保管情况进行定期检查，遇有特殊情况应立即检查，及时处理。"},{"i":17,"n":"第十七条","txt":"档案馆应积极创造条件，研究并应用新的科学技术，逐步实现档案管理的现代化。"},{"i":18,"n":"第十八条","txt":"档案馆应积极主动地开展利用工作，并根据党和国家有关规定开放历史档案。"},{"i":19,"n":"第十九条","txt":"档案馆应设立阅览室，积极改善阅览条件，为利用者提供方便。"},{"i":20,"n":"第二十条","txt":"档案馆应编制必要的检索工具和开放档案目录，印发档案馆指南等，为各方面广泛利用档案和资料提供方便条件。"},{"i":21,"n":"第二十一条","txt":"档案馆提供利用档案, 应遵循下列规定： 1.利用者查阅、摘录或复制档案，必须持本单位的正式介绍信，注明利用者的身份和利用档案的目的与范围。大量利用档案进行专题研究，必须事先将上级批准的研究计划抄送有关档案馆； 2.查阅、摘录、复制尚未开放的档案，须经馆长同意，必要时报请上级主管领导机关审查批准； 3.利用者需要采用复印、照相方法复制档案，均由档案馆负责办理，并按规定收费； 4.利用者所复制的档案（证明性材料除外），一律由馆方寄往利用者所在机关档案室保存，除经档案馆请示上级领导机关特许者外，均不得以任何形式全文公布、陈列、展出或再行复制，绝密档案复制件应于使用后交回； 5.港澳同胞、海外华侨和外国学者（包括外国留学生）利用档案，应按照国家的有关规定办理； 6.档案馆为利用者提供档案，应尽量以复制件代替原件。档案原件一般均不得借出馆外，如有特殊需要，须经主管领导人批准方可定期外借。"},{"i":22,"n":"第二十二条","txt":"档案馆应积极开展档案史料的研究和编纂工作，根据需要编辑档案文件汇集和其他参考资料，经主管领导人批准可公布档案文件。 省级以上和有条件的档案馆，要设立编研机构，有计划地编辑出版各种档案史料汇编。"},{"i":23,"n":"第二十三条","txt":"档案馆应举办各种形式的档案展览，参加或开展有关的学术研究活动。"},{"i":24,"n":"第二十四条","txt":"档案馆应及时、准确地掌握档案和资料的利用效果，不断改进利用工作。"},{"i":25,"n":"第二十五条","txt":"各类档案馆可根据本通则精神，制定本馆的实施办法。"},{"i":26,"n":"第二十六条","txt":"本通则自发布之日起施行。"}],"dianzigongwenguidangguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了加强对电子公文的归档管理，有效维护电子公文的真实性、完整性、安全性和可识别性，根据《中华人民共和国档案法》、《中华人民共和国档案法实施办法》和《国家行政机关公文处理办法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称的电子公文，是指各地区、各部门通过由国务院办公厅统一配置的电子公文传输系统处理后形成的具有规范格式的公文的电子数据。"},{"i":3,"n":"第三条","txt":"电子公文形成单位应指定有关部门或专人负责本单位的电子公文归档工作，将电子公文的收集、整理、归档、保管、利用纳入机关文书处理程序和相关人员的岗位责任。 机关档案部门应参与和指导电子公文的形成、办理、收集和归档等各工作环节。"},{"i":4,"n":"第四条","txt":"副省级以上档案行政管理部门负责对电子公文的归档管理工作进行监督和指导。 电子公文的真实性、完整性、安全性和可识别性，移交前由形成部门负责，移交后由档案部门负责。"},{"i":5,"n":"第五条","txt":"电子公文参照国家有关纸质文件的归档范围进行归档并划定保管期限。"},{"i":6,"n":"第六条","txt":"电子公文一般应在办理完毕后即时向机关档案部门归档。"},{"i":7,"n":"第七条","txt":"符合国家有关规定要求的电子公文可以仅以电子形式归档。电子公文归档应当符合电子文件归档和电子档案管理的要求。"},{"i":8,"n":"第八条","txt":"需要永久和长期保存的电子公文，应在每一个存储载体中同时存有相应的符合规范要求的机读目录。"},{"i":9,"n":"第九条","txt":"电子公文的收发登记表、机读目录、相关软件、其他说明等应与相对应的电子公文一同归档保存。"},{"i":10,"n":"第十条","txt":"电子公文的归档应在“全国政府系统办公业务资源网电子邮件系统”平台上进行，各电子公文形成单位档案部门应配置足够容量和处理能力及相对安全的系统设备。"},{"i":11,"n":"第十一条","txt":"电子公文形成单位应在运行电子公文处理系统的硬件环境中设置足够容量、安全的暂存存储器，存放处理完毕应归档保存的电子公文，以保证归档电子公文的完整、安全。"},{"i":12,"n":"第十二条","txt":"电子公文形成单位应在电子公文处理系统中设置符合安全要求的操作日志，随时自动记录对电子公文实时操作的人员、时间、设备、项目、内容等，以保证归档电子公文的真实性。"},{"i":13,"n":"第十三条","txt":"电子公文形成单位应在电子公文归档时按照国家有关要求对其真实性、完整性、可用性和安全性进行检查。"},{"i":14,"n":"第十四条","txt":"归档电子公文的移交形式可以是交接双方之间进行存储载体传递或通过电子公文传输系统从网上交接。"},{"i":15,"n":"第十五条","txt":"通过存储载体进行交接的归档电子公文，移交与接收部门均应对其载体和技术环境进行检验，确保载体清洁、无划痕、无病毒等。"},{"i":16,"n":"第十六条","txt":"归档电子公文应存储到符合保管要求的脱机载体上。归档保存的电子公文一般不加密，必须加密归档的电子公文应与其解密软件和说明文件一同归档。"},{"i":17,"n":"第十七条","txt":"归档的电子公文，应按本单位档案分类方案进行分类、整理，并拷贝至耐久性好的载体上，一式3套，一套封存保管，一套异地保管，一套提供利用。"},{"i":18,"n":"第十八条","txt":"档案部门应加强对归档电子公文的管理，提供利用有密级要求的归档电子公文，应严格遵守国家有关保密的规定，采用联网的方式提供利用的，应采取稳妥的身份认定、权限控制及在存有电子公文的设备上加装防火墙等安全保密措施。"},{"i":19,"n":"第十九条","txt":"超过保管期限的归档电子公文的鉴定和销毁，按照归档纸质文件的有关规定执行。对确认销毁的电子公文可以进行逻辑或物理删除，并应由档案部门列出销毁文件目录存档备查。"},{"i":20,"n":"第二十条","txt":"其他类型电子公文的归档管理可参照本办法。"},{"i":21,"n":"第二十一条","txt":"本办法未尽事宜，参照国家其他有关电子文件的标准和规定。"},{"i":22,"n":"第二十二条","txt":"本办法由国家档案局负责解释。"},{"i":23,"n":"第二十三条","txt":"本办法自2003年9月1日起施行。"}],"dianzidanganguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强和规范电子档案管理，确保电子档案真实、完整、可用、安全，促进档案工作更好服务党和国家工作大局、服务人民群众，根据《中华人民共和国档案法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"档案馆和机关、团体、企业事业单位以及其他组织（以下简称组织机构）的电子档案管理，适用本办法。 本办法所称电子档案，是指机关、团体、企业事业单位和其他组织以及个人在履行法定职责或者处理事务过程中，通过计算机等电子设备形成、办理、传输、存储的，对国家和社会具有保存价值并归档保存的各种信息记录。"},{"i":3,"n":"第三条","txt":"组织机构应当确保电子档案符合下列要求： （一）来源可靠。由合法、明确的形成者，在履行法定职责或者处理事务活动中产生，形成者、形成活动、形成时间可确认，形成、办理、整理、归档、保管、移交等系统安全可靠。 （二）程序规范。全过程管理符合国家相关法律法规以及标准规范的规定，并且准确记录、可追溯。 （三）要素合规。内容、结构、背景信息和管理过程信息等构成要素符合国家相关标准规范要求。 电子档案与传统载体档案具有同等效力，可以以电子形式作为凭证使用。"},{"i":4,"n":"第四条","txt":"组织机构应当配备必要的设施设备，建立管理机制、制度规范、安全措施、人才队伍，满足电子档案管理需求。"},{"i":5,"n":"第五条","txt":"组织机构应当加强电子档案全过程管理，确保承载形成、整理、归档、移交、接收、保管、处置、利用等各业务环节的应用系统之间相互衔接，并且持续进行元数据采集、维护等活动，完整记录电子档案管理过程。"},{"i":6,"n":"第六条","txt":"组织机构应当积极应用新一代信息技术，不断提升电子档案管理水平。"},{"i":7,"n":"第七条","txt":"机关、团体、企业事业单位和其他组织应当加强各类电子文件收集、归档工作，保障具有保存价值的电子文件应归尽归，并按规定移交档案馆。档案馆应当提升接收和管理各类电子档案的能力，保障电子档案应收尽收。"},{"i":8,"n":"第八条","txt":"电子档案管理的全过程应当符合国家网络安全、数据安全、个人信息保护、保密管理、密码管理等相关法律法规要求，确保电子档案的安全。"},{"i":9,"n":"第九条","txt":"国家档案主管部门统筹规划、组织协调、监督指导全国电子档案管理工作，研究制定政策制度，建立健全标准规范体系，推进电子档案安全保管和有效利用，推动电子档案全过程管理能力评估。 县级以上地方档案主管部门监督指导本行政区域内电子档案管理工作。 乡镇人民政府应当将电子档案管理纳入档案工作范围，并监督指导所属企业事业单位、基层群众性自治组织等的电子档案管理工作。"},{"i":10,"n":"第十条","txt":"按照国家规定应当形成档案的机关、团体、企业事业单位和其他组织应当履行下列职责： （一）确定管理电子档案的机构或者人员，将电子档案管理纳入档案工作责任制，纳入本单位信息化建设规划等，建立健全电子档案管理制度和规范，配备满足电子档案管理需要的信息化基础设施； （二）协调档案、文秘、业务、信息化、保密等职能部门共同推进电子档案管理，加强办公自动化系统、业务系统归档功能建设； （三）电子文件形成部门负责本部门电子文件的收集、整理、归档等工作； （四）管理电子档案的机构或人员负责本单位电子档案的管理，监督指导各部门电子文件的形成、收集、整理以及归档等工作，按照有关规定向档案馆移交电子档案。"},{"i":11,"n":"第十一条","txt":"档案馆应当履行下列职责： （一）建设满足电子档案长期保存和安全管理需要的信息化基础设施； （二）收集、保管和提供利用本馆分管范围内的电子档案； （三）建立健全本馆电子档案管理制度和规范。"},{"i":12,"n":"第十二条","txt":"档案主管部门应当加强与本行政区域有关信息化建设、电子政务建设、电子文件管理、数据管理、密码管理、保密管理等主管部门的工作协同，共同推进电子档案管理工作。"},{"i":13,"n":"第十三条","txt":"组织机构应当支持电子档案管理人员按照有关规定参加业务培训，电子档案管理人员应当具备相应的专业知识和技能。"},{"i":14,"n":"第十四条","txt":"机关、团体、企业事业单位和其他组织应当按照国家相关法律法规和标准规范的规定，确定本单位电子文件归档范围和电子档案保管期限、电子档案分类方案，并纳入本单位文件材料归档范围和档案保管期限表、档案分类方案进行管理。"},{"i":15,"n":"第十五条","txt":"机关、团体、企业事业单位和其他组织应当按照国家相关法律法规和标准规范形成、办理、传输、存储属于归档范围的电子文件，保证电子文件真实、完整、可用、安全，确保电子档案符合本办法第三条规定。 办公自动化系统、业务系统的归档功能应当符合相关标准规范，支撑电子文件收集、整理、归档等业务。"},{"i":16,"n":"第十六条","txt":"电子文件应当与元数据一并归档。电子文件归档格式应当具备开放、不绑定软硬件、显示一致性、可转换、易于利用等特性，并且能够支持向长期保存格式转换。电子文件元数据格式应当符合国家有关标准规范要求。"},{"i":17,"n":"第十七条","txt":"电子文件形成部门应当在电子文件形成、办理、收集过程中完成保管期限鉴定、分类、命名等工作，确保电子文件符合归档要求，并且完整采集描述电子文件内容、结构和背景信息的元数据及其整个管理过程元数据。 电子文件及其元数据归档不得采用非开放的压缩、加密等技术措施。 党政机关电子公文归档，应当去除电子印章的数字签名信息，只保留印章图形。其他组织机构电子文件归档可以参照处理。"},{"i":18,"n":"第十八条","txt":"电子文件形成部门和电子档案管理部门应当对提交归档的电子文件及其元数据等相关信息进行清点、登记，对其真实性、完整性、可用性、安全性进行检测，并由相关责任人确认。"},{"i":19,"n":"第十九条","txt":"电子档案管理部门应当对接收的电子档案进行审核、编制档号、确认保管期限等工作，确保电子档案符合档案管理要求。"},{"i":20,"n":"第二十条","txt":"机关、团体、企业事业单位和其他组织应当按照国家有关规定，定期向档案馆移交电子档案。档案馆应当做好接收工作，对于符合国家相关法律法规以及标准规范要求的电子档案，不得拒绝接收。 经同级档案主管部门同意，专业性较强或者需要保密的电子档案，可以按照国家有关规定延长向档案馆移交的期限。 经档案馆同意，对于未到国家规定移交期限的电子档案，明确划分在移交期限届满前该电子档案所涉及的利用、转换、迁移等权责后，可以提前交档案馆保管。涉及政府信息公开事项的，应当按照《中华人民共和国档案法》第十五条第二款规定办理。"},{"i":21,"n":"第二十一条","txt":"机关、团体、企业事业单位和其他组织向档案馆移交电子档案，应当符合下列要求： （一）按照国家关于电子档案移交与接收的标准规范要求对移交的电子档案进行组织，并进行真实性、完整性、可用性、安全性检测，合格后方可移交； （二）电子档案不保留电子印章的数字签名信息，只保留印章图形； （三）采用技术手段加密的电子档案应当去除加密措施后移交； （四）移交的电子档案应当附具到期开放意见、政府信息公开情况、密级变更情况等。"},{"i":22,"n":"第二十二条","txt":"档案馆应当按照国家相关标准规范要求对移交的电子档案进行真实性、完整性、可用性、安全性检测，合格后方可办理交接手续，接收登记入库。"},{"i":23,"n":"第二十三条","txt":"电子档案移交接收应当通过符合安全管理要求的网络和信息系统进行。不具备在线移交条件的，应当配备符合安全管理要求的存储介质进行离线移交，存储介质的选择和检测应当符合国家有关标准规范要求。"},{"i":24,"n":"第二十四条","txt":"机关、团体、企业事业单位和其他组织应当建设符合国家有关标准规范要求的电子档案管理信息系统，并与办公自动化系统、业务系统相互衔接。 档案馆应当建设符合国家有关标准规范要求的应用系统，支撑电子档案接收、存储、备份、鉴定、开发、利用、统计转换、迁移、销毁等工作。"},{"i":25,"n":"第二十五条","txt":"组织机构应当对电子档案、传统载体档案数字化成果等档案数字资源进行统一管理。 国家档案馆应当建设专用局域网络，配备服务器、存储、安全等设施设备，用于集中管理档案数字资源。"},{"i":26,"n":"第二十六条","txt":"组织机构应当加强电子档案备份工作，制定电子档案备份工作方案，对电子档案、电子档案管理信息系统等进行完整备份。 应当在磁介质、光介质、缩微胶片等介质中选择至少两种符合长期安全管理要求的存储介质，以在线方式和离线方式保存至少三套完整数据，每种介质上保存一套完整数据，一套在线应用，两套备份。应当制定检测策略，定期对电子档案可读状况、所处软硬件环境、存储介质完好程度等保管情况进行检测，发现问题及时处理，必要时对电子档案数据进行转换、迁移。"},{"i":27,"n":"第二十七条","txt":"档案馆应当对重要电子档案进行异地备份，根据需要有条件的档案馆可以建设灾难备份系统，实现重要电子档案及其管理信息系统的备份与灾难恢复。 机关、团体、企业事业单位和其他组织可以参照执行。 国家档案馆可以建设电子档案备份中心，提供电子档案备份服务。"},{"i":28,"n":"第二十八条","txt":"组织机构应当建立电子档案转换与迁移制度，经技术需求分析、风险评估，确有必要的，对电子档案、电子档案管理信息系统等进行转换、迁移，并留存操作过程记录。转换、迁移后，应当对电子档案进行真实性、完整性、可用性、安全性检测。"},{"i":29,"n":"第二十九条","txt":"组织机构应当定期对达到保管期限的电子档案进行鉴定。对仍需继续保存的电子档案，应当重新划定保管期限并变更相关管理数据。"},{"i":30,"n":"第三十条","txt":"电子档案销毁工作应当遵守国家有关规定，履行相关审批手续，禁止擅自销毁电子档案。 对需要销毁的电子档案，应当从在线存储设备、容灾备份等系统和离线存储介质中彻底删除，并记录被销毁电子档案的范围、数量、大小以及审核人、操作者等信息。"},{"i":31,"n":"第三十一条","txt":"电子档案的开放工作应当符合国家法律法规有关规定。档案馆应当通过网站或者其他方式定期公布开放电子档案目录。"},{"i":32,"n":"第三十二条","txt":"组织机构应当建立电子档案利用制度，采取有效管理措施和技术手段，充分利用政务网、互联网等渠道实现电子档案便利、高效、安全利用。"},{"i":33,"n":"第三十三条","txt":"利用者利用电子档案，应当遵守国家有关法律法规和档案利用的规定，不得擅自复制、篡改电子档案，不得损害国家利益、社会公共利益和其他主体合法权益。"},{"i":34,"n":"第三十四条","txt":"组织机构应当根据不同服务对象和利用范围，建立相应网络的档案数字资源利用服务平台。"},{"i":35,"n":"第三十五条","txt":"组织机构应当积极利用人工智能等信息技术，开展编研、展览和建设专题数据库等工作，不断开发档案数字资源。"},{"i":36,"n":"第三十六条","txt":"档案主管部门应当推动档案数字资源共享工作，促进跨区域、跨层级、跨部门共享利用。"},{"i":37,"n":"第三十七条","txt":"本办法由国家档案局负责解释。"},{"i":38,"n":"第三十八条","txt":"本办法自2024年11月1日起施行。"}],"kexuejishuyanjiudanganguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强科学技术研究档案(以下简称科研档案)管理，有效保护和利用科研档案，根据《中华人民共和国档案法》《科学技术档案工作条例》和国家科学技术管理有关法律、行政法规，结合科研工作和档案工作实际，制定本规定。"},{"i":2,"n":"第二条","txt":"承担科研项目（包括科研课题，下同）研究、计划管理的机关、团体、企业事业单位及其他组织开展科研档案管理工作适用本规定。"},{"i":3,"n":"第三条","txt":"科研档案是指科研项目在立项论证、研究实施及过程管理、结题验收及绩效评价、成果管理等过程中形成的，具有保存价值的文字、图表、数据、图像、音频、视频等各种形式和载体的文件材料以及标本、样本等实物。"},{"i":4,"n":"第四条","txt":"科研档案工作是科研管理的重要组成部分和科研活动的重要环节，各单位应当把科研档案工作要求纳入科研管理制度与工作流程，与科研项目工作同部署、同实施、同检查，将科研档案管理列入有关部门和人员的职责并予以考核。"},{"i":5,"n":"第五条","txt":"科研项目结题验收时，各单位应当按照分类分级管理的原则，按照有关规定对科研档案的完整性、准确性、系统性进行审查或验收。"},{"i":6,"n":"第六条","txt":"各单位应当按照集中统一管理原则，建立健全科研档案工作规章制度，在人员、库房、设备、经费等方面给予保障，保证科研档案工作顺利开展，确保科研档案完整、准确、可用、安全。 任何人不得以任何理由将应当归档的科研文件材料据为己有或拒绝归档。"},{"i":7,"n":"第七条","txt":"各单位应当把科研档案工作经费纳入本单位预算；科研档案工作产生的支出列入科研项目预算相关科目。"},{"i":8,"n":"第八条","txt":"按照国家档案工作统一领导、分级管理的原则，国家档案主管部门对全国科研档案工作实行监督和指导，国家科技主管部门在国家科技计划（专项、基金等）组织实施过程中加强科研档案工作的统筹协调。科研项目承担单位的上级主管部门（机构）应当把科研档案工作纳入本系统整体工作范畴，切实加强领导和管理。地方科技主管部门（机构）会同档案主管部门对本区域内科研档案工作实行监督和指导。"},{"i":9,"n":"第九条","txt":"中央和地方各级科技主管部门（机构）会同档案主管部门，对本级财政支持的科技计划（专项、基金等）的科研档案工作建立工作机制，并进行监督和指导。 中央财政资金支持的科研项目管理单位对所负责科研项目的档案工作负责，按照科技计划管理要求制定工作制度，建立工作机制。"},{"i":10,"n":"第十条","txt":"科研项目承担单位（含牵头承担单位）对所承担科研项目的档案工作负总责，对科研项目参加单位提出科研档案管理要求，明确档案归属与流向，并按照有关规定进行审查或验收。 科研项目参加单位应当按照国家有关规定及科研项目承担单位的要求做好所参加科研项目的文件材料收集、整理、归档及档案保管、利用、鉴定、处置等工作。"},{"i":11,"n":"第十一条","txt":"各单位档案管理部门集中统一管理本单位科研档案，对本单位科研文件材料的归档工作进行监督和指导，协助科研人员做好科研文件材料收集、整理、归档及科研项目结题验收等工作。"},{"i":12,"n":"第十二条","txt":"科研项目负责人对归档科研文件材料的完整性、准确性、系统性负责。"},{"i":13,"n":"第十三条","txt":"科研项目应当明确专人负责科研文件材料的收集、整理、审核，结题验收后按照要求及时归档。"},{"i":14,"n":"第十四条","txt":"各单位应当根据科研内容和科研管理程序，结合科研项目特点确定归档范围。科研项目在立项论证、研究实施及过程管理、结题验收及绩效评价、成果管理等全过程中形成的，具有保存价值的各种形式和载体的科研文件材料均应当纳入归档范围。 归档范围主要包括但不限于： （一）立项论证阶段 项目指南、可行性研究报告，项目经费预算文件材料，申报书及相关证明；立项评审文件材料，预算申诉、评审文件材料；立项（含预算）批复，任务合同书（含预算书）及各类协议等。 （二）研究实施及过程管理阶段 研究计划、组织实施工作方案，研究、实验任务书、大纲，实验、探测、测试、观测、观察、野外调查、考察等的原始记录和整理记录，综合分析报告；设计文件、图样，集成电路布图，工艺文件，计算文件，数据处理文件；科学数据；研制的样机、样品、标本等的实物及其目录、图片等。 中期、年度等阶段执行进展情况报告、总结报告、研究成果等；项目、人员、进度、经"},{"i":15,"n":"第十五条","txt":"科研文件材料归档要求： （一）归档的科研文件材料制成材料应当符合国家有关规范要求。 （二）科研项目完成或中止后，应当对所形成的科研文件材料加以系统整理，履行审查手续后及时归档；研究周期长的项目，可分阶段归档。 （三）科研文件材料归档时应当根据科研项目的性质、规模、创新性等确定保管期限。保管期限分为永久和定期，定期一般分为30年、10年。"},{"i":16,"n":"第十六条","txt":"科研电子文件的形成、收集、整理、归档及科研电子档案的保管、利用、鉴定、处置等应当按照国家电子文件归档和电子档案管理的有关规定进行。"},{"i":17,"n":"第十七条","txt":"各单位建设或使用科研项目管理系统时，应当充分考虑科研档案管理需要，设置科研电子文件归档管理功能或接口，并确保归档电子文件真实、完整、可用、安全。归档的科研电子文件及其存储格式、元数据等应当符合国家相关规范要求。"},{"i":18,"n":"第十八条","txt":"符合下列条件的单位，科研电子文件可仅以电子形式归档保存。 （一）形成的科研电子文件来源真实有效，由计算机等电子设备形成和传输。 （二）形成科研电子文件的系统能够准确、完整、有效接收和读取电子文件，能够输出符合国家标准归档格式的电子文件，设定了经办、审核、审批等必要的审签程序。 （三）使用的电子档案管理系统能够有效接收、管理、利用电子文件，功能符合电子档案的长期保管要求。 （四）采取有效措施，防止科研电子档案被篡改。 （五）建立科研电子档案备份制度，能够有效防范自然灾害、意外事故和人为破坏的影响。 （六）从外部接收的电子文件来源可靠、程序规范、要素合规。"},{"i":19,"n":"第十九条","txt":"科研档案应当按照《科学技术档案案卷构成的一般要求》（GB/T11822）进行整理，科研电子档案应当按照《电子文件归档与电子档案管理规范》（GB/T18894）进行整理。有条件的单位可以开展科研档案数字化。"},{"i":20,"n":"第二十条","txt":"科研档案的保管应当符合国家有关档案保管的要求，库容量满足未来档案增长的需要。科研档案保管过程中应当定期检查科研档案的保管状况，及时修复破损档案。 涉密科研档案应当按照国家有关规定保管。"},{"i":21,"n":"第二十一条","txt":"各单位档案部门应当按照国家有关规定对保管期满的科研档案进行鉴定。保管期满科研档案的鉴定应当由档案部门牵头，组织有关部门或人员共同进行。经鉴定仍需继续保存的科研档案应当重新划定保管期限，确无保存价值的应当按照有关规定进行销毁。"},{"i":22,"n":"第二十二条","txt":"各单位应当建立健全科研档案开放利用机制，促进科研档案信息共享，加强科研档案资源深度开发。科研档案的开发利用应当严格按照制度执行，符合知识产权保护要求，涉密科研档案的开发利用应当遵守国家有关保密规定。"},{"i":23,"n":"第二十三条","txt":"各单位应当建立科研档案工作统计制度，按照规定做好科研档案统计工作。"},{"i":24,"n":"第二十四条","txt":"分工合作完成的科研项目，应当以任务合同或分工协议条款等书面形式明确约定科研档案的归属、流向、处置和利用共享事项。一般应当由牵头承担单位保存一套完整档案。参加单位在保存本单位承担任务所形成档案的同时，将副本或复制件送交牵头承担单位。 如确系涉及参加单位或该单位科研人员合法权益而不宜向牵头承担单位送交副本或复制件，且有书面约定的，参加单位应当将本单位形成的科研档案目录送交牵头承担单位。"},{"i":25,"n":"第二十五条","txt":"对科研文件材料归档与科研档案管理工作做出突出贡献的单位和个人，应当给予表彰和奖励。"},{"i":26,"n":"第二十六条","txt":"违反本规定的单位和个人，根据《中华人民共和国档案法》《中华人民共和国档案法实施办法》《档案管理违法违纪行为处分规定》等予以处理。"},{"i":27,"n":"第二十七条","txt":"科研项目计划管理单位及项目综合管理形成的档案可按照文书档案管理。"},{"i":28,"n":"第二十八条","txt":"本规定由国家档案局、科学技术部负责解释，自2020年11月1日起施行。1987年3月20日国家科学技术委员会、国家档案局发布的《科学技术研究档案管理暂行规定》（国档发〔1987〕6号）同时废止。"}],"zhongdahuodonghetufashijiandanganguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强重大活动和突发事件档案科学管理，确保档案完整、安全与有效利用，更好地服务和推进国家治理体系和治理能力现代化，根据《中华人民共和国档案法》《中华人民共和国突发事件应对法》等相关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称重大活动是指在中华人民共和国境内外组织举办的，对党和国家、行业、地方具有重大意义或者重要国际影响的会议、会展、赛事、纪念、庆典等大型活动；突发事件是指突然发生，造成或可能造成严重社会危害，需要采取应急处置措施予以应对的自然灾害、事故灾难、公共卫生事件和社会安全事件。"},{"i":3,"n":"第三条","txt":"本办法所称重大活动和突发事件档案，是指在举办重大活动和应对突发事件过程中直接形成的对国家和社会具有保存价值的各种文字、图表、声像等不同形式的历史记录。"},{"i":4,"n":"第四条","txt":"重大活动和突发事件档案工作应当遵循统一领导、分级管理、分类实施、统筹协作的工作原则，维护档案完整与安全，推动档案利用与开发，为经济社会发展和突发事件应对活动提供文献参考和决策支持。"},{"i":5,"n":"第五条","txt":"各地区各部门应当加强对重大活动和突发事件档案工作组织领导，建立健全工作制度，保证档案管理做到收集齐全完整，整理规范有序，保管安全可靠，鉴定准确及时，利用简捷方便，开发实用有效。"},{"i":6,"n":"第六条","txt":"重大活动和突发事件档案的收集、整理、数字化和移交等工作所需经费应当纳入活动经费预算或保障措施。档案主管部门、档案馆开展重大活动和突发事件档案工作所需经费列入本级预算。"},{"i":7,"n":"第七条","txt":"重大活动和突发事件档案工作应当积极运用新技术、新手段，不断提升信息化管理水平。 涉及国家秘密的档案管理应当同时符合保密管理相关规定。"},{"i":8,"n":"第八条","txt":"档案主管部门负责本行政区域内重大活动和突发事件档案工作统筹协调、制度建设，负责建立本行政区域内重大活动和突发事件档案工作清单，对档案工作进行监督和指导。 中央国家机关根据档案管理需要，在职责范围内指导本系统的重大活动和突发事件档案业务工作。"},{"i":9,"n":"第九条","txt":"重大活动和突发事件的办理或应对部门，或者专门设立的临时机构（以下统称责任部门）负责相应档案的收集、整理和保管，并按规定向档案馆移交。 县级以上党委、政府作为主办单位的，执行单位作为责任部门履行前款规定的职责。"},{"i":10,"n":"第十条","txt":"档案馆负责分管范围内重大活动和突发事件档案接收征集、集中保管、编研开发并提供利用。 档案馆可以根据需要，提前介入重大活动和突发事件档案工作，并采取拍照、录音、录像等方式直接形成重大活动和突发事件档案。"},{"i":11,"n":"第十一条","txt":"档案主管部门、责任部门和档案馆应当建立档案主管部门统筹协调、各部门分工负责的工作机制，完善工作情况通报制度，协同推进重大活动和突发事件档案工作。"},{"i":12,"n":"第十二条","txt":"档案主管部门按照法定职权和程序对重大活动和突发事件档案管理工作进行监督检查，责任部门和档案馆应当配合。"},{"i":13,"n":"第十三条","txt":"对在重大活动和突发事件档案工作中做出突出贡献的单位或者个人，按照国家有关规定给予表彰、奖励。单位或个人存在违法违纪行为的，应当由档案主管部门、有关单位依法依规予以处理。"},{"i":14,"n":"第十四条","txt":"重大活动和突发事件档案工作实行清单管理制度。档案主管部门应当及时发布本行政区域重大活动和突发事件档案工作清单，明确年度工作任务（或事项）、责任部门、档案处置要求等。工作任务（或事项）应当包括但不限于以下内容： （一）党的代表大会、人民代表大会、政治协商会议，国际、国家或区域级论坛峰会、合作交流会、博览会、招商引资会、推介洽谈会等会议、会展活动； （二）国际、全国或地区性综合性运动会及其他重大杯赛、联赛、锦标赛、冠军赛等赛事活动； （三）以重大事件、重大纪念日、重要人物为主题的纪念、庆典活动； （四）自然灾害、事故灾难、公共卫生事件、社会安全事件应对活动。"},{"i":15,"n":"第十五条","txt":"责任部门应当制定重大活动和突发事件档案工作方案，明确档案工作负责部门和人员，按照工作程序和要求形成归档文件材料。采用业务系统办理业务的，业务系统应当支持形成符合要求的归档文件材料。"},{"i":16,"n":"第十六条","txt":"责任部门应当将重大活动和突发事件中形成的下列文件材料纳入收集范围，做到应收尽收、应归尽归： （一）领导指示、批示，机构成立及分工文件材料，工作制度、预案、方案、报告、报表、简报、总结，会议材料，奖惩材料，大事记、宣传报道，各单位按照分工或职责形成的其他文件材料； （二）照片、录音、录像； （三）业务数据、公务电子邮件、网页信息、社交媒体信息； （四）印章、题词、活动标志、证件、证书、纪念册、纪念章、奖杯、奖牌、奖章、奖状、牌匾、锦旗等实物档案； （五）其他具有保存利用价值的文件材料。"},{"i":17,"n":"第十七条","txt":"责任部门应当将重大活动和突发事件文件材料纳入本单位文件材料归档范围和档案保管期限表统一管理。责任部门为临时机构的，应当制定文件材料归档范围和档案保管期限表，经同级档案主管部门审查同意后施行。 中央国家机关、中央企业可以针对本系统重大活动和突发事件，制定本系统文件材料归档范围和档案保管期限表，经国家档案主管部门审查同意后施行。"},{"i":18,"n":"第十八条","txt":"重大活动和突发事件档案按照下列要求确定全宗设置： （一）责任部门为一个单位的，形成的档案纳入本单位档案全宗进行管理； （二）责任部门分为主办单位、协办单位的，形成的档案纳入主办单位档案全宗进行管理。存在多个主办单位或者分主办、承办单位的，形成的档案纳入承担活动主要工作的单位全宗进行管理或者协商确定； （三）责任部门为多个单位不分主次、联合开展工作的，形成的档案分别纳入各单位全宗进行管理； （四）责任部门为临时机构的，形成的档案纳入新设全宗或临时机构的主管单位全宗进行管理。 档案全宗设置产生争议的，由相关单位提交档案主管部门予以处理。"},{"i":19,"n":"第十九条","txt":"重大活动和突发事件档案一般与责任部门履行其他职能形成的档案进行统一管理，档案门类划分、分类方法与全宗内档案保持一致。确有必要的，可以设立专题进行管理。"},{"i":20,"n":"第二十条","txt":"责任部门应当按照相应门类档案整理规则对重大活动和突发事件文件材料进行组件（卷）、分类、排列、编号和编目等整理工作，并按要求及时归档。 重大活动和突发事件档案不论是否设立专题进行管理，都应当建立专题目录。"},{"i":21,"n":"第二十一条","txt":"责任部门应当在重大活动和突发事件应对工作结束6个月内，向同级档案主管部门报告档案工作方案落实情况。 例行性、周期性会议通过年度报告说明有关情况的，可以不再专门做出书面说明。"},{"i":22,"n":"第二十二条","txt":"责任部门应当按照国家有关规定向档案馆移交重大活动和突发事件档案，经档案馆同意，可以提前将档案交档案馆保管。责任部门为临时机构的，应当在临时机构停止工作前向有关主管单位或档案馆移交档案。 责任部门应当对移交进馆档案进行开放审核，并在移交时附具意见。"},{"i":23,"n":"第二十三条","txt":"档案馆应当按照国家有关规定接收重大活动和突发事件档案，并建立征集制度，通过接受捐献、购买、代存等方式收集档案，充实重大活动和突发事件档案资源。"},{"i":24,"n":"第二十四条","txt":"责任部门和档案馆应当按照国家有关规定配置适宜档案保存的库房和必要的设施、设备，确保档案的安全；采用先进技术，实现档案管理的现代化。"},{"i":25,"n":"第二十五条","txt":"档案馆和责任部门应当通过编制检索工具、建立检索系统、建设信息共享平台等方式，为重大活动和突发事件档案利用创造条件。 档案馆应当通过其网站或者其他方式定期公布开放档案的目录，为档案利用提供便利。"},{"i":26,"n":"第二十六条","txt":"档案馆应当积极推进利用工作，按照国家规定向单位或个人提供档案利用。责任部门利用已移交档案的，档案馆应当予以优先保证。 责任部门保管的档案对外提供利用的，需经本单位负责人批准。"},{"i":27,"n":"第二十七条","txt":"档案馆开展分管范围内重大活动和突发事件档案专题数据库建设，责任部门应当配合。责任部门档案以专题方式进行管理且具备建设条件的，应当开展本系统或本单位档案专题数据库建设。 档案主管部门应当科学规划专题数据库建设工作，推动档案馆和责任部门档案专题数据库共建共享共用。"},{"i":28,"n":"第二十八条","txt":"档案馆和责任部门应当加大对重大活动和突发事件档案资源开发力度，通过档案编研、陈列展览等形式，充分发挥档案价值，并为重大活动和突发事件应对提供决策参考。"},{"i":29,"n":"第二十九条","txt":"本办法由国家档案局负责解释。"},{"i":30,"n":"第三十条","txt":"本办法自2021年6月1日起施行。"}]};
